    }

    // ==================================================================
    //  技能与触发（2026-09-12）
    //
    //  这块以前**根本没有** —— 「部队卡发动技能」「触发效果」两类特效接不上，
    //  不是特效的问题，是引擎里没有这两种事件。这里逐条验：
    //    · 效果文法解析（解析不出来必须是 null，不许静默吞掉）
    //    · 五个触发类关键词的**时机**（照规则书 :161 那张 61 关键词表）
    //    · 主动技能的行动开销、不吃反击、和攻击目标规则的关系
    //    · 事件流本身（谁、在第几格、什么关键词）—— 表现层就靠它
    //    · 效果链的递归截断（反噬/忏悔互相触发天生是个环）
    // ==================================================================

    static bool HasSignal(BattleContext ctx, EvtKind kind, string keyword = null)
    {
        return FindSignal(ctx, kind, keyword) != null;
    }

    /// <summary>🆕 2026-10-18（`A985⑥`）：**留档日志**（`ctx.ActionLog`）里有没有这一种事件 ——
    /// 与 `HasSignal` 同一个道理，但看的是**不会被搬走**的那一份（`BattleDriver.RefreshBattleLog`
    /// 读的正是它）。⚠️ 两件事别混：`ClearSignals` **清不掉** `ActionLog`。</summary>
    static bool HasLog(BattleContext ctx, EvtKind kind)
    {
        foreach (var e in ctx.ActionLog) if (e != null && e.Kind == kind) return true;
        return false;
    }

    static BattleEvent FindSignal(BattleContext ctx, EvtKind kind, string keyword = null)
    {
        foreach (var e in ctx.Signals)
            if (e.Kind == kind && (keyword == null || e.Keyword == keyword)) return e;
        return null;
    }

    /// <summary>数「**誓约能力**发过几条 `Ability` 事件」（`keyword == "oath"`）。
    ///
    /// 🔴 为什么要数而不是只问「有没有」：`RuleCore.UseOathAbility` 的**判别式**是
    ///    「**付不起的那一次一条都不许发**」—— `HasSignal` 分不出「发过 1 条 / 发过 2 条」，
    ///    而这一条要判的正是**次数**（成功 1 条、失败 0 条）。
    /// ⚠️ 用例里**要先 `ctx.ClearSignals()`**：同一个 ctx 里前面成功过的那次会留下一条，
    ///    不清就永远数不出 0（那会让反例假通过）。
    /// </summary>
    static int OathAbilitySignals(BattleContext ctx)
    {
        int n = 0;
        foreach (var e in ctx.Signals)
            if (e.Kind == EvtKind.Ability && e.Keyword == "oath") n++;
        return n;
    }

    static void TestEffectSpecParsing()
    {
        var d = EffectSpec.Parse("Damage 2 EnemyUnit");
        CheckTrue(d != null, "「Damage 2 EnemyUnit」解析成功");
        if (d != null)
        {
            Check(d.Verb, "damage", "动词 = damage");
            Check(d.Amount, 2, "数值 = 2");
            Check(d.Target, EffectTargets.EnemyUnit, "目标 = enemyunit");
        }

        Check(EffectSpec.Parse("Heal 3 OwnWarlord").Target, EffectTargets.OwnWarlord, "Heal → OwnWarlord");
        Check(EffectSpec.Parse("Draw 2").Verb, "draw", "Draw 2 → draw（不用写目标）");
        Check(EffectSpec.Parse("Damage EnemyWarlord").Amount, 1, "省略数值 = 1");
        Check(EffectSpec.Parse("damage 1 enemyunit").Target, EffectTargets.EnemyUnit,
              "大小写不敏感");
        Check(EffectSpec.Parse("Damage 2 EnemyUnit").Short(), "DMG2 UNIT", "卡面小字 DMG2 UNIT");

        // ⚠️ 解析不出来一律 null —— **不给默认值、不猜**。
        //    「Damage 2」这种缺目标的，猜一个就等于替玩家做决定，而这工程最忌讳静默（见文件头）。
        CheckTrue(EffectSpec.Parse("Deal 3 damage to an enemy") == null,
                  "原版那种自然语言 → null（**故意的**，卡面会标 *）");
        CheckTrue(EffectSpec.Parse("Damage 2") == null, "Damage 没写目标 → null（不猜打谁）");
        CheckTrue(EffectSpec.Parse("Damage 2 SomeGuy") == null, "不认识的目标 → null");
        CheckTrue(EffectSpec.Parse("Frobnicate 1 Self") == null, "不认识的动词 → null");
        CheckTrue(EffectSpec.Parse("Damage -1 Self") == null, "负数值 → null");
        CheckTrue(EffectSpec.Parse("") == null, "空串 → null");
        CheckTrue(EffectSpec.Parse(null) == null, "null → null");
    }

    /// <summary>Rally（集结）：「从手牌部署后触发效果」—— 规则书 :200</summary>
    static void TestRally()
    {
        var rallier = Unit("Rallier", 1, 1, 3, "Rally: Damage 2 EnemyWarlord");
        var ctx = Battle(new[] { rallier, Unit("F1", 1, 1, 1), Unit("F2", 1, 1, 1) },
                         new[] { Unit("X", 1, 1, 1), Unit("Y", 1, 1, 1), Unit("Z", 1, 1, 1) });
        ToP1Turn(ctx, 2);

        int foeHp = ctx.Players[1].Warlord.Health;
        ctx.ClearSignals();
        CheckCode(RuleCore.PlayCard(ctx, 0, HandIdx(ctx, 0, "Rallier"), 3), RuleCodes.OK,
                  "Rallier 部署成功");

        Check(ctx.Players[1].Warlord.Health, foeHp - 2, "部署时 Rally 就打出去了（敌方督军 -2）");
        // 事件流：**Play → Deploy → Trigger → Hit**。**挨伤害也要发** ——
        // 表现层光看「血少了」分不出是挨刀、被技能打、还是疲劳。
        // ⚠️ 2026-09-13 起第一条是 `Play`（「打出了这张牌」）—— 加它是为了让**战术卡也有事件**
        //    （以前战术卡打出去一个事件都没有，战斗日志和表现层都看不见它），
        //    单位卡于是变成 Play + Deploy 两条。
        Check(ctx.Signals.Count, 4, "发了四条事件（Play + Deploy + Trigger + Hit）");
        Check(ctx.Signals[0].Kind, EvtKind.Play, "第 1 条是 Play（打出了这张牌）");
        Check(ctx.Signals[0].CardId, "Rallier", "Play 带着卡名");
        Check(ctx.Signals[1].Kind, EvtKind.Deploy, "第 2 条是 Deploy");
        Check(ctx.Signals[1].Slot, 3, "Deploy 带着格位");
        Check(ctx.Signals[1].CardId, "Rallier", "Deploy 带着卡名");
        Check(ctx.Signals[2].Kind, EvtKind.Trigger, "第 3 条是 Trigger");
        Check(ctx.Signals[2].Keyword, KeywordTable.Rally, "Trigger 带着关键词 rally");
        Check(ctx.Signals[2].Slot, 3, "Trigger 带着格位（表现层照它播特效）");
        Check(ctx.Signals[2].CardId, "Rallier", "Trigger 带着卡名");
        Check(ctx.Signals[3].Kind, EvtKind.Hit, "第 4 条是 Hit");
        Check(ctx.Signals[3].Amount, 2, "Hit 带着实际伤害值");
        Check(ctx.Signals[3].Player, 1, "Hit 的归属方是**挨打那边**（敌方督军）");

        // **留档日志**（`Ctx.ActionLog`）也在收：存的是同一份事件流，但**不会被搬走** ——
        // 而且把「出单位卡连着发的 Play + Deploy」**合并成一条**（不然每张单位卡都重复一行）。
        // 🔴 **2026-10-18（`A985⑥`）就地改口径（铁律 5）**：原来断的是 `ActionLog.Count == 3` ——
        //   那个字面量**依赖「推进回合不产生日志」**，而 `ToP1Turn` 里每一次**真·抽牌**现在都会记
        //   一条 `EvtKind.Draw`（`ActionLog` **不受 `ClearSignals` 影响**，上面那句 `ClearSignals`
        //   清不掉它）⇒ 3 这个数不再成立。**改成断尾部那三条**（原意图逐字保留：
        //   Play → Trigger → Hit），并且**反着加钉一条**：日志里**一条 `Deploy` 都不许有**
        //   —— 那正是「合并了」这件事本身（比原来的裸计数更结实）。
        int aLog = ctx.ActionLog.Count;
        CheckTrue(aLog >= 3, $"留档日志里至少三条（实测 {aLog} 条）");
        CheckTrue(!HasLog(ctx, EvtKind.Deploy),
                  "★ 留档日志里**没有 `Deploy`** —— 出单位卡的 Play + Deploy 真的合并了"
                + "（🧨 把 `AppendLog` 里那条合并删掉 ⇒ 本条红）");
        Check(ctx.ActionLog[aLog - 3].Kind, EvtKind.Play, "留档里倒数第 3 条是 Play（不是 Deploy）");
        Check(ctx.ActionLog[aLog - 2].Kind, EvtKind.Trigger, "留档里倒数第 2 条是 Trigger");
        Check(ctx.ActionLog[aLog - 1].Kind, EvtKind.Hit, "留档里最后一条是 Hit");

        // 没写 `Rally:` 效果的卡不会「触发了个寂寞」
        var plain = Unit("Plain", 1, 1, 3, KeywordTable.Rally);
        var ctx2 = Battle(new[] { plain, Unit("F1", 1, 1, 1), Unit("F2", 1, 1, 1) },
                          new[] { Unit("X", 1, 1, 1), Unit("Y", 1, 1, 1), Unit("Z", 1, 1, 1) });
        ToP1Turn(ctx2, 2);
        ctx2.ClearSignals();
        RuleCore.PlayCard(ctx2, 0, HandIdx(ctx2, 0, "Plain"), 3);
        CheckTrue(!HasSignal(ctx2, EvtKind.Trigger), "光有 rally 关键词、没写效果 → 不触发（也不发事件）");
    }

    /// <summary>Strike（猛击）攻击后触发 / Slay（斩杀）摧毁单位后触发 —— 规则书 :208 / :214</summary>
    static void TestStrikeAndSlay()
    {
        // ---- Strike：打没打死都算 ----
        UnitState a, b;
        var ctx = Duel(Unit("Striker", 2, 3, 5, "Strike: Damage 1 EnemyWarlord"),
                       Unit("Dummy", 1, 0, 9), out a, out b);
        ctx.ClearSignals();
        int foe = ctx.Players[1].Warlord.Health;
        CheckCode(RuleCore.DeclareAttack(ctx, 0, 3, 1, 3), RuleCodes.OK, "砍一刀（没砍死）");
        Check(Board(ctx, 1, 3).Health, 6, "目标 9 → 6");
        Check(ctx.Players[1].Warlord.Health, foe - 1, "Strike 在攻击后触发（敌方督军 -1）");
        var strike = FindSignal(ctx, EvtKind.Trigger, KeywordTable.Strike);
        CheckTrue(strike != null, "事件流里有 Strike");
        CheckTrue(strike != null && strike.Slot == 3, "Strike 事件带着攻击者的格位");

        // ---- Slay：攻击并**摧毁单位**后触发 ----
        var slayer = Unit("Slayer", 4, 5, 6, "Slay: Damage 2 EnemyWarlord");
        var ctx2 = Duel(slayer, Unit("Victim", 1, 0, 2), out a, out b);
        ctx2.ClearSignals();
        int foe2 = ctx2.Players[1].Warlord.Health;
        CheckCode(RuleCore.DeclareAttack(ctx2, 0, 3, 1, 3), RuleCodes.OK, "斩杀那一刀");
        Check(Board(ctx2, 1, 3), null, "目标被摧毁");
        Check(ctx2.Players[1].Warlord.Health, foe2 - 2, "Slay 触发（敌方督军 -2）");
        CheckTrue(HasSignal(ctx2, EvtKind.Trigger, KeywordTable.Slay), "事件流里有 Slay");

        // ---- 没打死 → 不触发 ----
        var ctx3 = Duel(slayer, Unit("Tank", 1, 0, 9), out a, out b);
        ctx3.ClearSignals();
        int foe3 = ctx3.Players[1].Warlord.Health;
        CheckCode(RuleCore.DeclareAttack(ctx3, 0, 3, 1, 3), RuleCodes.OK, "砍一刀（砍不死）");
        Check(ctx3.Players[1].Warlord.Health, foe3, "没摧毁单位 → Slay 不触发");
        CheckTrue(!HasSignal(ctx3, EvtKind.Trigger, KeywordTable.Slay), "事件流里也没有 Slay");

        // ---- 攻击者自己死了 → 两个都不触发（原文都写着「本单位存活时」）----
        var ctx4 = Duel(slayer, Unit("Brute", 1, 9, 3), out a, out b);
        ctx4.ClearSignals();
        int foe4 = ctx4.Players[1].Warlord.Health;
        CheckCode(RuleCore.DeclareAttack(ctx4, 0, 3, 1, 3), RuleCodes.OK, "同归于尽的一刀");
        Check(Board(ctx4, 0, 3), null, "攻击者阵亡");
        Check(ctx4.Players[1].Warlord.Health, foe4, "攻击者没活下来 → Slay 不触发");

        // ==================================================================
        //  🔴 `A1249` / `A1250`（2026-10-10 第十一会话）——
        //     **`Slay` / `Kills` 的【唯一判定口】**（`RuleCore.TryCreditKill`）
        //
        //  判据 = 原版 `CardScript__ResolveDeadCard.c:242-259`（**死亡结算**里那道
        //  「挑凶手去触发 `Slay(120)`」的闸；⛔ 不是 `AddTriggerSlay` 那条「强行触发某个单位的
        //  Slay」的路 —— 那条由 `AbilityEffect.triggerSlay(467)` 驱动，与「这一下是不是击杀」无关）。
        //  一道闸两个方向都错过：**多算**（`A1249`）与**少算**（`A1250`）。
        // ==================================================================

        // ---- ① `A1249`：**打掉一个【本身已是残骸】的格子，不算击杀** ----
        //   原版那一道 = `:256` 的 `*(char*)(local_308 + 0x65 /* isRemnant */) == 0`。
        //   残骸 `Health = 1`、挨任意一下就没 ⇒ 我们原来那一句 `!IsWarlord && !IsAlive` 放它过去。
        //   夹具：带 `Blood Thirst` 的斩杀单位一回合打两下 ——
        //     · 第 1 下打死一个**真单位**（它随即翻面成残骸）⇒ **算击杀**（`Slay` 响）；
        //     · 第 2 下打**已经翻面好的那具残骸** ⇒ **不算击杀**（`Slay` 不响）。
        //   🔴 **灭自证**：两支在**同一个上下文、同一个攻方、同一张卡**上，只差「被打的那一格
        //   是不是**已经**是残骸」这一个变量，却要求**相反**的结果 ⇒
        //    · 把 `IsRemnant` 那一句删掉 ⇒ 第 2 支红；
        //    · 把 Slay 整个关掉 ⇒ 第 1 支红 —— **两边不可能同时满足**。
        {
            var remSlay = new CardDef("FixtureRemnantSlay", "FixtureRemnantSlay", "unit", "",
                                      "common", "Test", 1, 0, 2, 0,
                                      new[] { KeywordTable.Remnant }, subtype: "Infantry");
            var ctx5 = ProbeBattle(new CardDef[0], new CardDef[0]);
            // 🔴 **2026-10-10（第十一会话 · `D2` 诊断 · 铁律 5）就地订正**：原来推 **4** 个回合 ⇒
            //   **P2 的督军被疲劳打到只剩 2 血**，而第 1 下的 `Slay: Damage 2 EnemyWarlord` **正好把它打死**
            //   ⇒ 对局结束 ⇒ **第 2 下 `DeclareAttack` 被 `RuleCore.cs:3015` 的 `ctx.IsOver` 拒掉**
            //   （返回 `ErrNotTurn(4)`）⇒ 下面两条红（而这**不是** `A1249` 的闸出错、也不是本会话的回归 ——
            //   是这条断言**从写下那天起就没绿过**）。
            //   ⚠️ **疲劳算得死**：本文件自己记过「推太远督军会被疲劳打死」（`:1249` / `:1414`「推到**第 8**
            //   个回合会打死」）—— **第 7 回合正好卡在「剩 2 血」这档**，推 4 步就够不着。
            //   ⇒ 推 **2** 步（P2 督军还剩 `30 − 1 − 3 = 26` 血量级）就够摆出「先打死真单位、再打残骸」。
            ToP1Turn(ctx5, 2);
            Place(ctx5, 0, 3, Unit("FSlayerBT", 1, 3, 9,
                                   "Blood Thirst", "Slay: Damage 2 EnemyWarlord"), exhausted: false);
            Place(ctx5, 1, 3, remSlay);                      // 2 血 ⇒ 第 1 下正好打死
            var lord = ctx5.Players[1].Warlord;
            int lordHp = lord.Health;
            // 🔴 **两条【具名前提】**（`D2` 建议补）：**不补的话**，夹具一旦再被推远，红会出现在**下面两条
            //   断言**上、读起来像「`A1249` 的闸坏了」—— 而真因是**这一局已经结束了**。
            CheckTrue(!ctx5.IsOver,
                      "★（前提）这一局**还没结束** —— `A1249` 的第 2 下必须真打得出"
                    + "（⚠️ 若本条红：先看 `ToP1Turn` 推了几步，**别去查 `A1249` 的闸**）" + LogTail(ctx5));
            CheckTrue(lordHp > 2,
                      "★（前提）敌方督军剩的血 **> 2** —— 否则第 1 下的 `Slay: Damage 2 EnemyWarlord`"
                    + " 会直接结束对局、第 2 下打不出来（实得 " + lordHp + "）" + LogTail(ctx5));

            CheckCode(RuleCore.DeclareAttack(ctx5, 0, 3, 1, 3), RuleCodes.OK,
                      "第 1 下：打一个**真单位**");
            var occ = Board(ctx5, 1, 3);
            CheckTrue(occ != null && occ.IsRemnant,
                      "★（前提）它翻面成残骸了 —— 同一格还占着（`CheckIfDead.c:110-147`）"
                      + LogTail(ctx5));
            Check(lord.Health, lordHp - 2,
                  "★ 第 1 支：**打死真单位 ⇒ 算击杀**（敌方督军 -2）—— 这一支改前改后都该绿"
                  + LogTail(ctx5));

            int lordHp2 = lord.Health;
            CheckCode(RuleCore.DeclareAttack(ctx5, 0, 3, 1, 3), RuleCodes.OK,
                      "第 2 下：打**已经是残骸**的那一格（`Blood Thirst` 给的第二次攻击）");
            CheckTrue(Board(ctx5, 1, 3) == null, "★（前提）那具残骸被摧毁了（离开了格位）");
            Check(lord.Health, lordHp2,
                  "★★【`A1249`】**打掉一具【已经是残骸】的格子不算击杀** —— 原版 `:256` 的闸是 "
                  + "`isRemnant == 0`；我们原来那一句 `!IsWarlord && !IsAlive` 放它过去了"
                  + LogTail(ctx5));
        }

        // ---- ② `A1250`：**用能力 / 效果摧毁也算击杀** ----
        //   原版那道闸允许 `local_28 == 0x14 /* UnitDeathType.ability(20) */`
        //   （另一个被放行的是 `0xf /* combatDefender(15) */` = 我们的**攻击**那一路）；
        //   我们原来 `killed` **只在 `DeclareAttack` 里算** ⇒ 效果击杀**一次都不触发**。
        //   夹具：一个同时带 `Ability: Damage 3 EnemyUnit` 与 `Slay: Damage 2 EnemyWarlord`
        //   的单位，用**技能**打死一个 3 血敌人 ⇒ 它自己的 `Slay` 要响。
        {
            var caster = new CardDef("FixtureSlayCaster", "FixtureSlayCaster", "unit", "",
                                     "common", "Test", 3, 2, 9, 0,
                                     new[] { "Ability: Damage 3 EnemyUnit",
                                             "Slay: Damage 2 EnemyWarlord" },
                                     subtype: "Infantry");
            var ctx6 = ProbeBattle(new CardDef[0], new CardDef[0]);
            ToP1Turn(ctx6, 4);
            Place(ctx6, 0, 3, caster, exhausted: false);
            var prey = Place(ctx6, 1, 3, Unit("FPrey", 1, 0, 3), exhausted: true);
            var lord = ctx6.Players[1].Warlord;
            int lordHp = lord.Health;

            CheckCode(RuleCore.UseAbility(ctx6, 0, 3, 3), RuleCodes.OK,
                      "放技能（3 点打一个 3 血的目标）");
            CheckTrue(!prey.IsAlive,
                      "★（前提）**技能把它打死了** —— 这一下不是攻击" + LogTail(ctx6));
            Check(lord.Health, lordHp - 2,
                  "★★【`A1250`】**效果 / 能力击杀也算一次击杀** ⇒ 施放者自己的 `Slay` 响（督军 -2）。"
                  + "改之前这一格**一次都不触发**（`killed` 只在 `DeclareAttack` 里算）"
                  + LogTail(ctx6));
        }

        // ---- ②′ `A1250` 的**灭自证**：同一发伤害，**由战术卡打出**时【不算】击杀 ----
        //   原版 `UnitDeathType` 里 `ability(20)` 与 `tactic(30)` 是**两档**，
        //   而那道闸只放行 `combatDefender(15)` / `ability(20)` ⇒ **战术卡的伤害不算击杀**。
        //   我们这边同一条事实的另一面：战术卡那条路上 `ctx.ActingUnit == null` ⇒ **没有「凶手」这张牌**
        //   （原版 `param_1` 遍历的是**场上那批牌**，战术卡不在里面）。
        //   🔴 这一支挡住的是「把**所有**死亡都记给『施放方』」那种实现 ——
        //   它与 ② 只差「打这一下的是不是一张**在场上**的牌」。
        {
            var mk = Tactic("T_A1250Tactic", 0, "Deal 3 damage to an enemy");
            var ctx7 = ProbeBattle(new[] { mk }, new CardDef[0]);
            ToP1Turn(ctx7, 4);
            Place(ctx7, 0, 3, new CardDef("FixtureSlayWatcher", "FixtureSlayWatcher", "unit", "",
                                          "common", "Test", 1, 0, 9, 0,
                                          new[] { "Slay: Damage 2 EnemyWarlord" },
                                          subtype: "Infantry"), exhausted: true);
            Place(ctx7, 1, 3, Unit("FPreyT", 1, 0, 3), exhausted: true);
            var lord = ctx7.Players[1].Warlord;
            int lordHp = lord.Health;
            CheckCode(RuleCore.PlayTactic(ctx7, 0, HandIdx(ctx7, 0, "T_A1250Tactic"), 3), RuleCodes.OK,
                      "用**战术卡**打死一个 3 血的单位");
            CheckTrue(Board(ctx7, 1, 3) == null, "★（前提）它死了" + LogTail(ctx7));
            Check(lord.Health, lordHp,
                  "★★【`A1250` 灭自证】**战术卡**的伤害不算任何人的击杀 —— "
                  + "原版 `UnitDeathType` 里 `tactic(30)` 与 `ability(20)` 是两档，那道闸只放行后者"
                  + "（我们这边 = 那条路上没有 `ActingUnit`）" + LogTail(ctx7));
        }
    }

    /// <summary>Backlash（反噬）：「单位死亡时触发效果」—— 规则书 :169</summary>
    static void TestBacklash()
    {
        UnitState a, b;
        var ghost = Unit("Ghost", 2, 0, 3, "Backlash: Damage 2 EnemyWarlord");
        var ctx = Duel(Unit("Killer", 1, 5, 5), ghost, out a, out b);
        ctx.ClearSignals();

        int p1hp = ctx.Players[0].Warlord.Health;     // Ghost 在 P2 场上，反噬打的是 P1 的督军
        CheckCode(RuleCore.DeclareAttack(ctx, 0, 3, 1, 3), RuleCodes.OK, "打死反噬单位");
        Check(Board(ctx, 1, 3), null, "Ghost 阵亡");
        Check(ctx.Players[0].Warlord.Health, p1hp - 2, "Backlash 在阵亡时触发，打到对方督军");

        var death = FindSignal(ctx, EvtKind.Death);
        var back = FindSignal(ctx, EvtKind.Trigger, KeywordTable.Backlash);
        CheckTrue(death != null && death.Player == 1 && death.Slot == 3,
                  "Death 事件带着**原格位**（格位马上就空了，不带上就没法播特效）");
        CheckTrue(back != null && back.Player == 1 && back.Slot == 3,
                  "Backlash 事件也带着原格位（单位已经不在棋盘上了）");

        // 先发 Death 再结算反噬 —— 顺序反了的话表现层会在「人已经没了」之后才收到阵亡
        int di = ctx.Signals.IndexOf(death), bi = ctx.Signals.IndexOf(back);
        CheckTrue(di >= 0 && bi > di, "Death 排在 Backlash 前面");
    }

    /// <summary>
    /// 🔴 **2026-10-17：进弃牌堆 / 阵亡登记 两笔账排在反噬之后**（`RuleCore.CleanupDeaths` 下移）。
    ///
    /// **原版判据 = `d:/2/tools/decomp_full/` 的逐跳方法体**（不是我们自己的 `rule_core.gd`）：
    ///   ① `CardScript__CheckIfDead.c:124` 生命归零 → `state(0x228) = 5`（濒死）；
    ///      `:135` 当场 `TriggerUnitBacklashActions` —— **反噬在这一跳**。
    ///   ② `CardScript__TriggerUnitBacklashActions.c:99` 把反噬包成 action
    ///      `BattleManager.AddAutoActionToQueue` 入队 ⇒ 它自己一次都不碰墓地。
    ///   ③ 死亡触发那一族（`CardScript__ResolveDeadCard.c`：`TriggerOnMinionDeath` /
    ///      `BroadcastUnitRequiem` / `OnTrigger(0x1ae)`）里**一次`Cemetery` 都没有**。
    ///   ④ `BattleManager__AddToCemetery.c` 在全量反编译里**只有一个调用者** ——
    ///      `CardScript__GoToCemetery.c:17`；而 `GoToCemetery` 只在
    ///      `CardScript._UnitDeath_d__446__MoveNext.c:152` 被调用 —— 那是 `UnitDeath`
    ///      协程的**最后一跳**（之前已经 `WaitForSeconds` 两次：`:126` / `:383`）。
    /// ⇒ 「反噬结算时它**还没**进弃牌堆、也**还没**进阵亡表」是原版语义；
    ///    「反噬打死的人**先于**死者进弃牌堆」也是（各走各的死亡链，进墓地在各自链尾）。
    ///
    /// ⚠️ **判别式**：把 `ps.Discard.Add` / `ctx.DeadUnits.Add` 挪回反噬**之前**，
    ///    下面 ① 与 ③ 两条立刻变红（② 也会）。三条都不是同义反复 ——
    ///    ① 量的是「效果看不看得见」，③ 量的是**弃牌堆里的次序**，② 量的是「跑完之后真的登记了」。
    /// </summary>
    static void TestDeathAccountsAfterBacklash()
    {
        // ---- ① + ②：反噬**看得到**「还没登记」；跑完之后**就看得见了** ----
        //    探测器 = 条件句 `If a friendly troop died this turn` —— 它读的正是 `ctx.DeadUnits`
        //    （`EffectResolver.ConditionHolds` 的 `case "deaths"`：逐条判
        //      `Owner == owner && DeathTurn == ctx.Turn && MatchesKind(卡, "troop")`）。
        var probe = Unit("FixtureDiedProbe", 1, 0, 1,
                         "Backlash: If a friendly troop died this turn, Deal 3 damage to the enemy Warlord");
        // 🚧 **护栏**：正文没解析出来的话，① 会「因为压根没效果」而假绿 —— 先把它钉住。
        // 🔴 **2026-10-17 收口时修（这条护栏当场抓到了一个真错）**：正文原来写的是
        //    `… Damage 3 EnemyWarlord` —— `If …, <正文>` 这层壳是 **`EffectText`（原版卡面文法）**，
        //    而载荷 `Damage 3 EnemyWarlord` 是 **`EffectSpec`（我们自己设计的 26 张卡的封闭文法，
        //    `EffectSpec.cs` 文件头明写 `EnemyWarlord` 是它的目标词表）** ⇒ **两套文法串进了一句**：
        //    ① `CardDef.AddTriggerOp` 只走 `EffectText.Parse`（没有 `EffectSpec` 兜底），而
        //       `EffectText.ReDeal` 认 `Deal N damage to …`、**不认 `Damage N X` 这种语序** ⇒ 解析 0 条 op；
        //    ② 退路 `u.Effect(keyword)`（`EffectSpec`）要求首词 ∈ {damage,heal,draw}，而首词是 `If` ⇒ null。
        //    ⇒ `FireTriggerAt` 在门口 `return false`，**反噬一次都不发生** ⇒ 第二条断言（期望 27）实得 30。
        //    ⚠️ **不是解析器缺口**：全池「`关键词: If …`」共 13 条、**13/13 都解析得出**；
        //    「触发正文里用 `EffectSpec` 语序」的形状**全池 0 条、只在夹具里**。
        //    ⇒ 改后两句文法一致，**条件句仍由 `deaths` 支现判**（正是这条测试要量的东西）。
        //    判据与三态离线实测 → `资料/普查产出_1017/D_Backlash条件句_诊断.md`。
        // 🔴 **2026-10-17 裁定：上面那条护栏（连同它护的夹具正文）【另开一件】= 账 `A942`** ——
        //    ⛔ 不在 F1 那一件（收口自检第一次大修）里顺手改。
        //    · **为什么另开**（写手请裁、主对话当天裁的，它给的理由站得住）：
        //      ① `ConditionHolds("deaths")` 那条支里的 `MatchesKind(卡, "troop")` 与夹具
        //         `type == "unit"` **能不能过，谁都没验** ⇒ 护栏自己的前提就悬着；
        //      ② **正文一改，①/② 两条断言的期望值本身就要重定**（现在钉的是「3 点**没打出来**」）
        //         ⇒ 那是**改用例语义**，不是修一处笔误。
        //    · **判据出处**：`资料/待办判据_1018.md`「2026-10-17 · 收口自检第一次大修（F1–F4）」
        //      那一行的末段（原文：「🔴 裁定（它请我裁的 `:16288` 那条护栏）：**另开一件**」）；
        //      本轮只读现核 = `资料/普查产出_1018第三会话/RECON_剩余账册.md` 的 `A942` 一节
        //      （⚠️ 它同时订正**落点**：护栏在**本文件**的 `TestDeathAccountsAfterBacklash`，
        //       **不在** `Editor/BattleScene.cs` —— 账上那句落点写错了）。
        //    · **现状（2026-10-18 仍未判）**：①② 一条都还没判 ⇒ ⛔ 别把「正文已经改通」当成
        //      `A942` 已收口 —— 改的是**解析得通不通**，没验的是**条件句判得对不对**。
        CheckTrue(probe.TriggerOps(KeywordTable.Backlash) != null,
                  "🚧 夹具自检：`Backlash: If a friendly troop died this turn, Deal 3 damage …`"
                  + "**正文解析出来了**（没解析出来的话下面两条是假绿，不是真过）");
        {
            var ctx = Battle(new CardDef[0], new CardDef[0]);
            ToP1Turn(ctx, 1);
            Place(ctx, 0, 3, Unit("FixtureReaperA", 1, 1, 9), exhausted: false);
            Place(ctx, 0, 5, Unit("FixtureReaperB", 1, 1, 9), exhausted: false);
            Place(ctx, 1, 3, probe, exhausted: true);          // 第一只探针
            Place(ctx, 1, 5, probe, exhausted: true);          // 第二只探针（同一个 CardDef，另一份实例）
            int w0 = ctx.Players[0].Warlord.Health;

            CheckCode(RuleCore.DeclareAttack(ctx, 0, 3, 1, 3), RuleCodes.OK, "A 刀砍死第一只探针");
            Check(Board(ctx, 1, 3), null, "第一只探针阵亡");
            Check(ctx.Players[0].Warlord.Health, w0,
                  "★ ① 它**自己的**反噬看不到自己已阵亡（此刻 `DeadUnits` 里还没有它）"
                  + " ⇒ 条件句不成立、3 点**没打出来**。⚠️ 把两笔账挪回反噬**之前**，"
                  + "这条会变成减去 3 的值 —— 那一版就是我们改之前的错顺序");

            // ② 反噬跑完之后：它**真的**登记了（两笔账一起写）
            CheckTrue(ctx.DeadUnits.Exists(d => d.Owner == 1 && d.Card != null
                                                && d.Card.Name == "FixtureDiedProbe"),
                      "★ ② 反噬结束之后，它**已经在阵亡表里**"
                      + "（这一条把「下移到反噬之后」和「压根没记」分开）");
            CheckTrue(ctx.Players[1].Discard.Count == 1
                      && ctx.Players[1].Discard[0].Card.Name == "FixtureDiedProbe",
                      "★ ② 同时它**也进了弃牌堆** —— `Discard` 与 `DeadUnits` 一起下移、一起写"
                      + "（`TakeFromGraveyard` 那条「只写一处」的规矩不变）");

            // ②-b 第二只探针的反噬**看得见第一只了** ⇒ 「登记确实发生在反噬之后、而且真的生效」
            // ⚠️ 格位用 `SlotOf` 现查 —— 第一只死掉之后连续棋盘会补位，别写死槽号。
            int bSlot = SlotOf(ctx, 0, "FixtureReaperB");
            int p2Slot = SlotOf(ctx, 1, "FixtureDiedProbe");
            CheckTrue(bSlot >= 0 && p2Slot >= 0,
                      "第二把刀与第二只探针都还在场上（" + bSlot + " / " + p2Slot + "）");
            CheckCode(RuleCore.DeclareAttack(ctx, 0, bSlot, 1, p2Slot), RuleCodes.OK, "B 刀砍死第二只探针");
            Check(ctx.Players[0].Warlord.Health, w0 - 3,
                  "★ ② 第二只探针的反噬**打得出来**（3 点）—— 第一只已经在阵亡表里了"
                  + "（同回合、同主人）。⚠️ 反噬要是排在登记**之后**看，这条也就不成立");
        }

        // ---- ③ 判别式（弃牌堆的**次序**）：嵌套死亡时，被反噬打死的**先于**死者进弃牌堆 ----
        //    每次死亡各走自己的链、进墓地在**各自链尾** ⇒ 内层先跑完、先入档。
        //    ⚠️ 这正是「反噬 / 自爆打死别人」时两笔账下移会改变的那一处 —— 与下移**同源**，
        //       不是副作用：原版 `GoToCemetery` 也是各条 `UnitDeath` 协程的尾。
        {
            var ctx = Battle(new CardDef[0], new CardDef[0]);
            ToP1Turn(ctx, 1);
            // 🔴 **2026-10-17（F1 修 · δ）**：Killer **自己也要有反噬正文** —— 链条是
            //    Killer 打死 outer → outer 的反噬打死 Killer → **Killer 的反噬打死 inner**
            //    （作者自己的设计文档就这么写的：`资料/普查产出_1017/W_弃牌堆先后.md:57`）。
            //    原来漏了第 5 参（`Unit(name, cost, atk, hp, params string[] kws)`，见本文件 `Unit`），
            //    ⇒ Killer 一次都没反噬 ⇒ inner 永远不死 ⇒ 同块三条 ✗（inner 离场 / 阵亡表次序 /
            //    弃牌堆两张）**同一根因**。
            //    ⚠️ 正文与下面 outer / inner 那两张**逐字相同** —— 那是本文件里**已经跑通**的写法
            //    （`:15018` 的 `FixtureVengeful` 用它；本轮实跑日志 `_tmp_view/ruleengine.log:27398`
            //      「✓ Killer 被 outer 的反噬打死」= 同一句确实被引擎结算了）。
            Place(ctx, 0, 3, Unit("FixtureNestedKiller", 1, 1, 4, "Backlash: Deal 4 damage to all enemies"),
                  exhausted: false);   // 4 血：撑得过反击、撑不过反噬
            Place(ctx, 1, 3, Unit("FixtureNestedOuter", 1, 0, 1, "Backlash: Deal 4 damage to all enemies"),
                  exhausted: true);
            Place(ctx, 1, 5, Unit("FixtureNestedInner", 1, 0, 1, "Backlash: Deal 4 damage to all enemies"),
                  exhausted: true);

            CheckCode(RuleCore.DeclareAttack(ctx, 0, 3, 1, 3), RuleCodes.OK, "砍死 outer");
            Check(Board(ctx, 0, 3), null, "Killer 被 outer 的反噬打死（4 血 · 挨 4 点）");
            // ⚠️ 别用 `Board(ctx,1,5) == null` 判 inner 死了 —— 连续棋盘会补位，格位会挪，
            //    那条断言在「没死但挪了」时也绿。改为**按名字查格位**（找不到才是真的离场）。
            CheckTrue(SlotOf(ctx, 1, "FixtureNestedInner") < 0, "inner 被 Killer 的反噬打死、离场");
            int iInner = ctx.DeadUnits.FindIndex(d => d.Card != null && d.Card.Name == "FixtureNestedInner");
            int iOuter = ctx.DeadUnits.FindIndex(d => d.Card != null && d.Card.Name == "FixtureNestedOuter");
            CheckTrue(iInner >= 0 && iOuter >= 0 && iInner < iOuter,
                      "★ ③ 阵亡表里的次序**也是内层在前**（两笔账同源、一起下移）");

            var disc = ctx.Players[1].Discard;
            Check(disc.Count, 2, "P2 的弃牌堆里恰好两张");
            // 🔴 **2026-10-17（F1 修 · α）：先拼成串再比，⛔ 不许索引。**
            //    原来是 `CheckTrue(disc[0].Card… && disc[1].Card…)` —— **先索引、不断长度**。
            //    上一条（`disc.Count == 2`）一报红，紧跟的 `disc[1]` 就**越界抛异常**、
            //    把整条自检打断（2026-10-17 实况：其后约 49 个用例一条没跑，
            //    见 `资料/普查产出_1017/D1_崩溃诊断.md` §A）。
            //    ⛔ **别改成 `if (disc.Count >= 2)`** —— 那会把「不足两张」变成**静默不判**
            //    （弱断言）；拼成串比则「只有一张」「零张」都照实报出来。
            var seq = new List<string>();
            foreach (var d in disc) seq.Add(d != null && d.Card != null ? d.Card.Name : "?");
            string seqStr = string.Join(",", seq);
            Check(seqStr, "FixtureNestedInner,FixtureNestedOuter",
                  "★ ③ **嵌套死亡的次序**：被反噬打死的 `inner` **先于** `outer`（死者本人）进弃牌堆"
                  + " —— 两张实际是 [" + seqStr + "]；"
                  + " 把两笔账挪回反噬**之前**，这里会变成 [outer, inner]");
            Check(ctx.Players[0].Discard.Count, 1, "P1 那边只有 Killer 进了弃牌堆");
        }
    }

    /// <summary>Penitence（忏悔）：「受到伤害但未死亡时触发效果」—— 规则书 :196</summary>
    static void TestPenitence()
    {
        UnitState a, b;
        var penitent = Unit("Penitent", 2, 0, 5, "Penitence: Damage 1 EnemyWarlord");

        var ctx = Duel(Unit("Poker", 1, 2, 5), penitent, out a, out b);
        ctx.ClearSignals();
        int p1hp = ctx.Players[0].Warlord.Health;
        CheckCode(RuleCore.DeclareAttack(ctx, 0, 3, 1, 3), RuleCodes.OK, "打一下但没打死");
        CheckTrue(Board(ctx, 1, 3) != null, "Penitent 还活着");
        Check(ctx.Players[0].Warlord.Health, p1hp - 1, "受伤未死 → Penitence 触发");

        // 打死了就不触发 —— 「未死亡」是这条的关键字，那种情况归 Backlash 管
        var ctx2 = Duel(Unit("Poker", 1, 9, 5), penitent, out a, out b);
        ctx2.ClearSignals();
        int p1b = ctx2.Players[0].Warlord.Health;
        CheckCode(RuleCore.DeclareAttack(ctx2, 0, 3, 1, 3), RuleCodes.OK, "一击打死");
        Check(Board(ctx2, 1, 3), null, "Penitent 阵亡");
        Check(ctx2.Players[0].Warlord.Health, p1b, "死了就不走 Penitence（那条只管「未死亡」）");
        CheckTrue(!HasSignal(ctx2, EvtKind.Trigger, KeywordTable.Penitence), "事件流里没有 Penitence");

        // Shield 全挡 = 没受伤 → 也不触发
        var shielded = Unit("Shielded", 2, 0, 5, KeywordTable.Shield, "Penitence: Damage 1 EnemyWarlord");
        var ctx3 = Duel(Unit("Poker", 1, 2, 5), shielded, out a, out b);
        ctx3.ClearSignals();
        int p1c = ctx3.Players[0].Warlord.Health;
        CheckCode(RuleCore.DeclareAttack(ctx3, 0, 3, 1, 3), RuleCodes.OK, "打在盾上");
        Check(ctx3.Players[1].Board[3].Health, 5, "Shield 挡住了，一滴血没掉");
        Check(ctx3.Players[0].Warlord.Health, p1c, "没真受伤 → Penitence 不触发");
    }

    /// <summary>主动技能：花掉一次行动、**不吃反击**</summary>
    static void TestAbility()
    {
        UnitState a, b;
        var caster = Unit("Caster", 3, 2, 5, "Ability: Damage 3 EnemyUnit");
        var ctx = Duel(caster, Unit("Prey", 1, 4, 6), out a, out b);
        ctx.ClearSignals();
        int energy = ctx.Players[0].Energy;

        CheckCode(RuleCore.CanUseAbility(ctx, 0, 3, 3), RuleCodes.OK, "有技能、没疲劳、目标合法 → 可以放");
        CheckCode(RuleCore.UseAbility(ctx, 0, 3, 3), RuleCodes.OK, "放技能成功");

        Check(Board(ctx, 1, 3).Health, 3, "Prey 6 → 3（技能 3 点）");
        CheckTrue(Board(ctx, 0, 3).Exhausted, "放技能花掉了这个单位的行动");
        Check(Board(ctx, 0, 3).Health, 5, "**技能不吃反击** —— 施法者一滴血没掉（Prey 4 攻）");
        Check(ctx.Players[0].Energy, energy, "放技能不花能量");

        CheckTrue(HasSignal(ctx, EvtKind.Ability), "事件流里有 Ability —— 这一类以前压根没有");
        var ab = FindSignal(ctx, EvtKind.Ability);
        Check(ab.Slot, 3, "Ability 事件带着施法者的格位");
        Check(ab.CardId, "Caster", "Ability 事件带着卡名");
        Check(ab.Keyword, KeywordTable.Ability, "Ability 事件带着关键词");
        Check(ab.Amount, 3, "Ability 事件带着数值（卡面/日志用）");

        CheckCode(RuleCore.CanUseAbility(ctx, 0, 3, 3), RuleCodes.ErrExhausted, "一回合只能行动一次");
        CheckCode(RuleCore.CanUseAbility(ctx, 1, 3, 3), RuleCodes.ErrNotTurn, "非本方回合不能放技能");

        // 没有技能的单位
        var ctx2 = Duel(Unit("Mundane", 1, 1, 1), Unit("Dummy", 1, 0, 1), out a, out b);
        CheckCode(RuleCore.CanUseAbility(ctx2, 0, 3), RuleCodes.ErrNoAbility, "卡上没写 Ability → ErrNoAbility");
        CheckCode(RuleCore.UseAbility(ctx2, 0, 3), RuleCodes.ErrNoAbility, "UseAbility 也拒绝");
    }

    /// <summary>
    /// 技能**不是攻击** —— 攻击目标那三条限制里只有「潜行」管得着它。
    /// 三条的原文见 `RuleCore.CanUseAbility` 的注释（规则书 :223 / :188 / :211）。
    /// </summary>
    static void TestAbilityTargetRules()
    {
        UnitState a, b;
        var caster = Unit("Caster", 3, 2, 5, "Ability: Damage 3 EnemyUnit");
        var ctx = Duel(caster, Unit("Guard", 1, 1, 9, KeywordTable.Vanguard), out a, out b);

        CheckCode(RuleCore.CanUseAbility(ctx, 0, 3, 3), RuleCodes.OK,
                  "先锋不挡技能（原文是「不能被选为**攻击目标**」）");

        // 飞行同理 —— 原文是「只能被…以**近战攻击**选中」
        Place(ctx, 1, 2, Unit("Bird", 1, 1, 5, KeywordTable.Flying));
        CheckCode(RuleCore.CanUseAbility(ctx, 0, 3, 2), RuleCodes.OK, "飞行也不挡技能");

        // 潜行是「不能被**任何方式**选中」—— 这条管得着
        Place(ctx, 1, 3, Unit("Lurker", 1, 1, 5, KeywordTable.Stealth));
        CheckCode(RuleCore.CanUseAbility(ctx, 0, 3, 3), RuleCodes.ErrTarget, "潜行挡技能");

        // 目标合法性：空格 / 督军 / 越界
        CheckCode(RuleCore.CanUseAbility(ctx, 0, 3, 8), RuleCodes.ErrTarget, "空格 → 目标非法");
        CheckCode(RuleCore.CanUseAbility(ctx, 0, 3, BoardSpec.WarlordSlot), RuleCodes.ErrTarget,
                  "选不中督军 —— 要打督军的技能，目标栏会直接写 EnemyWarlord");

        // 攻击者自己不存在 / 格位越界
        CheckCode(RuleCore.CanUseAbility(ctx, 0, 0), RuleCodes.ErrNotUnit, "空格上放技能");
        CheckCode(RuleCore.CanUseAbility(ctx, 0, 99), RuleCodes.ErrNotUnit, "越界格位");

        // ⚠️「能不能开始放」和「这个目标行不行」是两件事。
        //    要选目标的技能，表现层得先**进入选目标状态**（那一步还没选呢）——
        //    拿要求目标的判据去问只会得到 ErrTarget，于是永远进不了那个状态（踩过）。
        CheckCode(RuleCore.CanStartAbility(ctx, 0, 3), RuleCodes.OK, "CanStartAbility 不判目标");
        CheckCode(RuleCore.CanUseAbility(ctx, 0, 3), RuleCodes.ErrTarget,
                  "CanUseAbility 不带目标 → 「还没选目标」");
    }

    /// <summary>
    /// **「这一下会打死它」那条预览的【逐条】口径**（2026-10-08 `W8b3`；**2026-10-09 按用户裁决改了次序**）。
    ///
    /// 🔴🔴 **2026-10-09 用户拍板（`A1107`）：预览的条目次序改照【真实落地】，不再照原版预览那一套。**
    ///    原版自己两套次序不同、而 `dodge` / `Shield` **只挡第 0 条** ⇒ 两套对
    ///    「带盾/闪避 + 攻方有星镖」给出**相反**的「会不会死」：
    ///      · 预览 `CardHighlight__ToggleCombatPreviewHighlight.c:62-81` = `[主伤害, 星镖, 标记光]`（**改前我们照的**）；
    ///      · 落地 `BattleManager__RecordAttackPendingDamage.c:59-84` + `ReceiveDamage` = `[星镖, 标记光, 主伤害]`。
    ///    ⇒ 现在 `RuleCore.AttackDamageEntries` = **`[星镖, 主伤害, 标记光]`**（三段各自独立、
    ///      照**结算**次序；标记光**不并进**主伤害）。
    ///    🔑 **本方法里凡「原版 = …」的期望值，指的都是原版 `EnoughPendingDamageToDieWithDamageValues`
    ///    那套【逐条】算法本身**（护甲每条各扣一次、盾/闪避只跳第 0 条）—— 那几条判据没变；
    ///    变的是**喂进去的条目次序与拆分**，出处 = 用户拍板，别「改回原版」。
    ///
    /// 判据 = 原版两份反编译（全文与行号 → `RuleCore.DamageAfterReductionOne` 上面那一段）：
    ///   · `CardScript__EnoughPendingDamageToDieWithDamageValues.c:115-119` ——
    ///     `dodge`(240) / `shield`(80) **只在第 0 条**跳过；`invulnerable`(310) **任意条目**都跳过。
    ///   · 同文件 `:138-156` —— `armour > 0 &amp;&amp; dmg > 0 ⇒ dmg = Math.Max(1, dmg − armour)`，**每一条各扣一次**。
    ///
    /// 🔴 **期望值一律写死算出来的那个数**（不拿被测函数反推）—— 每组里都写着「= …」。
    /// 🔴 **灭自证自 2026-10-09 起换口径**：**预览合计必须【等于】真打一局的实际掉血**
    ///    （`DeclareAttack` 真跑一次、比血量差）—— 这才是这条预览存在的理由。
    ///    旧口径「预览 ≠ 合计版（`DamageAfterReduction`）」**已不再成立也不该成立**：
    ///    那个「合计版」是**单次 `Hurt` 一个数**的口径，**不代表攻击的落地序列**，拿它当基准是错的。
    /// </summary>
    static void TestWillDiePreviewEntries()
    {
        // ---- (a) 主动技能那一路：伤害条目要**真算得出来**（不是恒 0 / 恒 false）----
        //  原版 `EntityScript__GetActiveAbilityDamage.c`：遍历 ability 逻辑，
        //  `chosenAbility ∈ {doDamage 10, doDamageMultiRandom 12, doDamageAndDestroySelf 15}`
        //  **且** `targetsAffected == 30 (TargetsAffected.target)` ⇒ 累加 `minDamage`。
        {
            UnitState a, b;
            var caster = Unit("Caster2", 3, 2, 5, "Ability: Damage 3 EnemyUnit");
            var ctx = Duel(caster, Unit("Prey2", 1, 0, 3), out a, out b);

            var entries = RuleCore.ActiveAbilityDamageEntries(ctx, 0, 3, 1, 3);
            Check(entries.Count, 1,
                  "主动技能路 = **1 条**（原版 `ToggleCombatPreviewHighlight.c:88` 只往表里 Add 一次）");
            Check(entries[0], 3, "★ 那一条 = 技能伤害 **3**（原版 = `minDamage`）");
            Check(RuleCore.ActiveAbilityDamage(ctx, 0, 3, 1, 3), 3,
                  "`ActiveAbilityDamage`（原版那个 int 返回形态）= **3**");
            CheckTrue(RuleCore.WouldKillByEntries(Board(ctx, 1, 3), entries),
                      "★ 3 血的目标挨 3 点 ⇒ **会死**"
                    + "（改之前 `SetReticleTarget` 把技能路整条排除 ⇒ 恒 false）");
            Board(ctx, 1, 3).Health = 4;
            CheckTrue(!RuleCore.WouldKillByEntries(Board(ctx, 1, 3), entries),
                      "★ 反例：4 血 ⇒ 不会死（不是恒 true）");
        }
        //  反例：**不是「所有技能都算成会死」** —— 三个都不是「打到玩家点的那个敌人」的来源。
        {
            UnitState a, b;
            var medic = Unit("Medic2", 2, 1, 4, "Ability: Heal 3 OwnWarlord");
            var ctx = Duel(medic, Unit("Dummy2", 1, 0, 9), out a, out b);
            Check(RuleCore.ActiveAbilityDamageEntries(ctx, 0, 3, 1, 3).Count, 0,
                  "反例：治疗技能 0 条（原版 `chosenAbility` 不是那三个伤害值）");

            var warlordHitter = Unit("Wh2", 2, 1, 4, "Ability: Damage 3 EnemyWarlord");
            var ctx2 = Duel(warlordHitter, Unit("Dummy3", 1, 0, 9), out a, out b);
            Check(RuleCore.ActiveAbilityDamageEntries(ctx2, 0, 3, 1, 3).Count, 0,
                  "反例：`Damage 3 EnemyWarlord` 0 条（原版那是 `TargetsAffected.enemyWarlord` 那一档，不是 `target`）");

            //  裸 `Deal 3 damage`（**没写目标**）= 原版 `TargetsAffected.lowestHealth`(=240)
            //  —— `EntityScript.GetActiveAbilityDamage` 只认 `target`(=30) ⇒ **不计入**。
            //  这一条同时钉住誓约那条来源的守卫（`CanUseOathAbility` 通过、但 op 被判掉）。
            var autoHitter = new CardDef("AutoOath", "AutoOath", "unit",
                                         "Oath 1: Deal 3 damage", "common", "Test", 2, 1, 4, 0, null);
            var ctx3 = Duel(autoHitter, Unit("Dummy4", 1, 0, 9), out a, out b);
            Check(ctx3.Players[0].Board[3].Card.OathOps.Count, 1, "（前提）誓约正文收进 `OathOps` 了");
            Check(RuleCore.CanUseOathAbility(ctx3, 0, 3), RuleCodes.OK, "（前提）这一手誓约能用");
            Check(RuleCore.ActiveAbilityDamageEntries(ctx3, 0, 3, 1, 3).Count, 0,
                  "反例：裸 `Deal 3 damage` 0 条 —— 原版那是 `lowestHealth`(=240)，只认 `target`(=30)");
        }

        // ---- (b-1) **护甲 × 多条目**：每条各扣一次（`:138-156`）----
        //  条目 [星镖 3, 主伤害 2]（**落地次序**）、护甲 2 ⇒ Max(1,3−2) + Max(1,2−2) = 1 + 1 = **2**
        {
            UnitState a, b;
            var atk = Unit("ArmorProbe", 1, 2, 9, "Shuriken 3");
            var ctx = Duel(atk, Unit("Armored", 1, 0, 9, "Armour 2"), out a, out b);
            var t = Board(ctx, 1, 3);
            Check(t.Armor, 2, "（前提）目标护甲 2");

            var entries = RuleCore.AttackDamageEntries(ctx, 0, 3, 1, 3, false);
            Check(entries.Count, 2,
                  "攻击路 2 条 = **[星镖, 主伤害]**（落地次序；用户 2026-10-09 裁决 `A1107`）");
            Check(entries[0], 3, "…[0] **星镖 3**（落地时它先单独打一次）");
            Check(entries[1], 2, "…[1] **主伤害 2**");
            Check(RuleCore.DamageAfterReductionList(t, entries), 2,
                  "★ 逐条：Max(1,3−2) + Max(1,2−2) = 1+1 = **2**");
            // 🔴【灭自证·**2026-10-09 换的新口径**】预览合计必须**等于**真打一局的实际掉血。
            //   旧口径「预览 ≠ `DamageAfterReduction(整包)`」已废：那个整包版是**单次 `Hurt` 一个数**，
            //   **不代表攻击的落地序列**（落地是两次 `Hurt`），拿它当基准是把错的当对的。
            Check(RuleCore.DeclareAttack(ctx, 0, 3, 1, 3), RuleCodes.OK, "（前提）攻击声明成功");
            Check(t.Health, 7,
                  "★【灭自证】真打一局 = 星镖 Max(1,3−2)=1，主伤害 Max(1,2−2)=1 ⇒ 9−2 = **7**；"
                + " 预览合计 2 与它**相等**（把次序改回 [主伤害, 星镖] 这里不一定会红，"
                + " 但 (b-2)/(b-2b) 那两组带盾的必红）");
        }
        //  条目 [3, 3]、护甲 2 ⇒ Max(1,3−2) + Max(1,3−2) = 1 + 1 = **2**
        {
            UnitState a, b;
            var atk = Unit("ArmorProbe2", 1, 3, 9, "Shuriken 3");
            var ctx = Duel(atk, Unit("Armored2", 1, 0, 9, "Armour 2"), out a, out b);
            var t = Board(ctx, 1, 3);
            var entries = RuleCore.AttackDamageEntries(ctx, 0, 3, 1, 3, false);
            Check(entries[0], 3, "（前提）[0] 星镖 3（两条都是 3 ⇒ 次序在这一组里看不出来）");
            Check(entries[1], 3, "（前提）[1] 主伤害 3");
            Check(RuleCore.DamageAfterReductionList(t, entries), 2,
                  "★ 逐条：条目 [3,3] ⇒ 1+1 = **2**");
            Check(RuleCore.DeclareAttack(ctx, 0, 3, 1, 3), RuleCodes.OK, "（前提）攻击声明成功");
            Check(t.Health, 7, "★ 真打一局也是 9−2 = **7** ⇒ 与预览一致");
        }

        // ---- (b-2) **盾 / 闪避 + 星镖**：只跳过**第 0 条**，而第 0 条现在 = **星镖**（`:115-119`）----
        //  条目 [星镖 3, 主伤害 2]（**落地次序**）、目标带 Shield、3 血 ⇒ 0 + 2 = **2** ⇒ **不会死**（剩 1）
        //  🔴 **这就是 `A1107` 那条裁决要修的东西**：改前预览第 0 条是**主伤害** ⇒ 报 0 + 3 = 3 ⇒ 「**会死**」，
        //     而真打一局是「盾被星镖吃掉、主伤害 2 照落」⇒ 3 血剩 **1** ⇒ 「**不会死**」—— **方向相反**。
        {
            UnitState a, b;
            var atk = Unit("ShieldProbe", 1, 2, 9, "Shuriken 3");
            var ctx = Duel(atk, Unit("Shielded", 1, 0, 3, "Shield"), out a, out b);
            var t = Board(ctx, 1, 3);
            CheckTrue(t.HasShield, "（前提）目标带 Shield");
            var entries = RuleCore.AttackDamageEntries(ctx, 0, 3, 1, 3, false);
            Check(entries.Count, 2, "（前提）条目 = **[星镖 3, 主伤害 2]**");
            Check(RuleCore.DamageAfterReductionOne(t, entries[0], 0), 0,
                  "★ 第 0 条（**星镖**）被 Shield 挡下 = **0**（原版 `:117` 那个 `shield` 条件）");
            Check(RuleCore.DamageAfterReductionOne(t, entries[1], 1), 2,
                  "★ 第 1 条（**主伤害**）**照算** = **2**（原版那两个条件都带 `|| iVar11 != 0`）");
            Check(RuleCore.DamageAfterReductionList(t, entries), 2, "★ 逐条合计 = 0 + 2 = **2**");
            CheckTrue(!RuleCore.WouldKillByEntries(t, entries),
                      "★ 2 点打 3 血 ⇒ **不会死**（改前预览报「会死」—— 方向相反，这就是 A1107）");
            // 🔴【灭自证】真打一局必须给出同一个数（盾被星镖吃掉 ⇒ 主伤害照落）
            Check(RuleCore.DeclareAttack(ctx, 0, 3, 1, 3), RuleCodes.OK, "（前提）攻击声明成功");
            Check(t.Health, 1, "★【灭自证】真打一局：3 − 2 = **1**（盾挡的是星镖、不是主伤害）");
            CheckTrue(!t.HasShield, "…盾**被消耗**掉了（在星镖那一下）");
        }
        //  `dodge` 与 `shield` **同一条规则**（原版 `:115-118` 那两个条件是并列的）。
        //  🔴 **就地订正（2026-10-08，当天晚些的 `A1077`）**：这一段原来写着
        //     「`dodge` 在我们引擎里本来**完全没有**……这一份是它的第一处落地，且**只在预览这一层**」——
        //     **前半句当时是对的、后半句已经不对了**：`A1077` 当天就把**结算侧**也补上了
        //     （`DamageAfterReduction` + `ApplyDamage`，关键词也进了 `KeywordTable`）。
        //     ⇒ 现在 `dodge` 是**预览 / 结算两条路各一支**，**本方法只管预览那一支**；
        //       结算那一支的断言全在 `TestDodgeKeyword` 里，别在这里抄第二份。
        {
            UnitState a, b;
            var atk = Unit("DodgeProbe", 1, 2, 9, "Shuriken 3");
            var ctx = Duel(atk, Unit("Dodger", 1, 0, 3), out a, out b);
            var t = Board(ctx, 1, 3);
            t.AddKeyword("dodge", 1);
            CheckTrue(t.Has("dodge"), "（前提）目标带 dodge");
            var entries = RuleCore.AttackDamageEntries(ctx, 0, 3, 1, 3, false);
            Check(RuleCore.DamageAfterReductionOne(t, entries[0], 0), 0,
                  "dodge：第 0 条（**星镖 3**）被跳过 = 0");
            Check(RuleCore.DamageAfterReductionList(t, entries), 2,
                  "★ dodge 与 shield 同规则：只跳第 0 条 ⇒ **主伤害 2 照落**");
            Check(RuleCore.DeclareAttack(ctx, 0, 3, 1, 3), RuleCodes.OK, "（前提）攻击声明成功");
            Check(t.Health, 1, "★【灭自证】真打一局 3 − 2 = **1** ⇒ 与预览合计一致");
        }
        //  `invulnerable` **任意条目**都跳过（原版 `:119` 它不在 `iVar11 != 0` 那一组里）
        {
            UnitState a, b;
            var atk = Unit("InvulnProbe", 1, 2, 9, "Shuriken 3");
            var ctx = Duel(atk, Unit("Invuln", 1, 0, 1, "Invulnerable"), out a, out b);
            var t = Board(ctx, 1, 3);
            var entries = RuleCore.AttackDamageEntries(ctx, 0, 3, 1, 3, false);
            Check(entries.Count, 2, "（前提）两条");
            Check(RuleCore.DamageAfterReductionList(t, entries), 0,
                  "★ invulnerable：**两条都跳过**（不像盾/闪避只跳第 0 条）");
        }

        // ---- (b-3) **markerlight 是独立的一条、且排在【主攻击之后】**（**结算**次序）----
        //  原版 `_ResolveAttack_d__438__MoveNext.c`：星镖 `:618` → 主伤害 `:1116` → 标记光 `:1251`；
        //  标记光是**自己一次 `ReceiveDamage`**（`:1279`）⇒ 护甲对它**另扣一次**。
        //  条目 [主伤害 3, 标记光 2]、护甲 1 ⇒ Max(1,3−1) + Max(1,2−1) = 2 + 1 = **3**
        //  🔴 **2026-10-09（`A1107`）这一组改过两次**：先按【登记】次序并成一条（**错**），
        //     再按用户补充裁决改回「三条独立、标记光排第三」。⛔ 别并回去、也别挪到主伤害之前。
        {
            UnitState a, b;
            var atk = Ranged("MlProbe", 1, 1, 9, 3);
            var ctx = Duel(atk, Unit("Marked", 1, 0, 9, "Markerlight 2", "Armour 1"), out a, out b);
            var t = Board(ctx, 1, 3);
            Check(t.KwValue("markerlight"), 2, "（前提）目标带 Markerlight 2");

            var entries = RuleCore.AttackDamageEntries(ctx, 0, 3, 1, 3, true);
            Check(entries.Count, 2, "★ 2 条：主伤害 + 标记光（**标记光是独立一条**，不并进主伤害）");
            Check(entries[0], 3, "…[0] 主伤害（远程）**3**");
            Check(entries[1], 2, "…[1] 标记光 **2**（结算次序里它排**最后**）");
            Check(RuleCore.DamageAfterReductionList(t, entries), 3,
                  "★ 逐条（护甲 1）：Max(1,3−1) + Max(1,2−1) = 2 + 1 = **3**");
            Check(RuleCore.DeclareAttack(ctx, 0, 3, 1, 3, true), RuleCodes.OK, "（前提）远程攻击声明成功");
            Check(t.Health, 6,
                  "★【灭自证】真打一局：9 − 3 = **6**（主伤害 2 + 标记光 1，护甲各扣一次）"
                + " —— 与预览合计一致（并成一条的话护甲少扣一次 ⇒ 这里必红）");
            // 近战**不**计入标记光（原版 `:1252` 那个 `param_1+0x58 == 2` 就是「只远程」）
            UnitState c, d;
            var ctx2 = Duel(Ranged("MlProbe2", 1, 1, 9, 3),
                            Unit("Marked2", 1, 0, 9, "Markerlight 2", "Armour 1"), out c, out d);
            Check(RuleCore.AttackDamageEntries(ctx2, 0, 3, 1, 3, false).Count, 1,
                  "…近战 1 条、且不含标记光（结算也只在远程那一支读它）");
            Check(RuleCore.AttackDamageEntries(ctx2, 0, 3, 1, 3, false)[0], 1,
                  "…那一条 = 近战攻击力 **1**（不是 3，也不含标记光 2）");
        }

        // ---- 回归：**实际结算用的那一份没动**（合计版与 `WouldKill` 还是老口径）----
        {
            UnitState a, b;
            var ctx = Duel(Unit("RegA", 1, 2, 9), Unit("RegB", 1, 0, 2, "Shield"), out a, out b);
            var t = Board(ctx, 1, 3);
            Check(RuleCore.DamageAfterReduction(t, 2), 0, "回归：合计版对带盾目标 = 0（没动）");
            CheckTrue(!RuleCore.WouldKill(t, 2), "回归：`WouldKill`（`EffectResolver.PreferKillable` 读它）= 不会死");
        }
        //  单条目、无盾/闪避/护甲时，两条口径必须**一致**（否则就是「逐条版另写了一支」）
        {
            UnitState a, b;
            var ctx = Duel(Unit("EqA", 1, 4, 9), Unit("EqB", 1, 0, 3, "Armour 1"), out a, out b);
            var t = Board(ctx, 1, 3);
            Check(RuleCore.DamageAfterReductionOne(t, 4, 0), 3, "（一致性）单条目版第 0 条 = 4−1 = **3**");
            Check(RuleCore.DamageAfterReduction(t, 4), 3, "…与合计版在单条目时一致");
        }
    }

    /// <summary>
    /// **`Dodge`（闪避）—— 关键词登记 + 结算侧那一支**（2026-10-08 `A1077`）。
    ///
    /// 背景：`W8b3` 只做了**预览**那一半（`DamageAfterReductionOne` / `…List`）。那时 `dodge`
    /// 在引擎里**整条都没有**：① `KeywordTable.Prefixes` 里没有它 ⇒ 卡数据写 `Dodge` 会被
    /// `Normalize` 判 null 后**静默丢弃**；② 结算侧（`ApplyDamage` → `DamageAfterReduction`）
    /// 没有该分支。⇒ 本方法钉的就是这两条。
    ///
    /// 判据（原版两份反编译，逐句读过；全文与行号 → `RuleCore.ApplyDamage` 那一支的注释）：
    ///   · **挡下** `CardScript__GetAdjustedDamage.c:36-48` —— `0xf0`(dodge) 与 `0x50`(shield)
    ///     **并列**写进同一个 `uVar3 = 1`；
    ///   · **消耗** `CardScript._ReceiveDamage_d__381__MoveNext.c:320-333` —— dodge 与 shield
    ///     **各占一段独立的 `if`**（不是 `else if`）⇒ 同挡、同消耗；两者同时在身时**一起被消耗**；
    ///   · **预览只跳第 0 条** `CardScript__EnoughPendingDamageToDieWithDamageValues.c:115-119`。
    ///
    /// 🔴 **期望值一律写死算出来的那个数**，不拿被测函数反推。
    /// 🔴 **灭自证**有三处：①「带 dodge ⇒ 0」与「不带 ⇒ 3」是同一形状的**两个方向**；
    ///    ②被挡之后必须**真的被消耗**（否则下一刀还是 0）；③🔴 **2026-10-09（`A1107` 用户裁决）换了口径** ——
    ///    预览合计必须**等于真打一局的实际掉血**（第 (7) 组真跑一次 `DeclareAttack` 比血量差）。
    ///    ⛔ 旧口径「预览 ≠ `DamageAfterReduction(整包)`」**已废**：整包版是「单次 `Hurt` 一个数」，
    ///    **不代表攻击的落地序列**，拿它当基准是把错的当对的（当时的期望值 3 vs 0 也是错的）。
    /// </summary>
    static void TestDodgeKeyword()
    {
        // ---- (1) **登记**：`Dodge` 现在认得出、进得去关键词表（原来会被静默丢掉）----
        {
            Check(KeywordTable.Normalize("Dodge"), KeywordTable.Dodge,
                  "★ `Dodge` 认得出（改前 `Normalize` 返回 null ⇒ 卡数据写它会被**静默丢弃**）");
            Check(KeywordTable.Normalize("Dodge."), KeywordTable.Dodge,
                  "…卡面那种带句号的 `Dodge.` 也认得出");
            CheckTrue(KeywordTable.Implemented.Contains(KeywordTable.Dodge),
                      "★ 而且进了 `Implemented` —— 否则卡面会白打 `*`、`UnimplementedKeywords` 会多报一条");
            var parsed = KeywordTable.Parse(new[] { "Dodge" });
            Check(parsed.ContainsKey(KeywordTable.Dodge), true,
                  "★ 卡数据 `keywords:[\"Dodge\"]` 真的进了关键词表（不再静默丢弃）");
        }

        // ---- (2) **结算侧**：第 0 条（这一下）被挡下 + 消耗；**后续条目照算** ----
        //  原版 `GetAdjustedDamage.c:41`（dodge 命中 ⇒ 挡下）+
        //  `…MoveNext.c:320-325`（挡下之后 `RemoveTrait(0xf0)` ⇒ 只挡这一次）。
        {
            UnitState a, b;
            var ctx = Duel(Unit("DodgeAtk", 1, 2, 9), Unit("DodgeDef", 1, 0, 6), out a, out b);
            var t = Board(ctx, 1, 3);
            t.AddKeyword(KeywordTable.Dodge, 1);
            CheckTrue(t.Has(KeywordTable.Dodge), "（前提）目标带 dodge");

            int hp0 = t.Health;                                   // 6
            int first = RuleCore.ApplyDamage(ctx, t, 3, "自检");
            Check(first, 0, "★ 结算侧：第 0 条（这一下 3 点）被 Dodge **整个挡下** = **0**");
            Check(t.Health, hp0, "…血量一点没动（不是「减到最低 1」）");
            CheckTrue(!t.Has(KeywordTable.Dodge),
                      "★ 而且 Dodge 被**消耗**掉了（原版那一段 `RemoveTrait(0xf0)`）");

            int second = RuleCore.ApplyDamage(ctx, t, 3, "自检");
            Check(second, 3, "★ 后续条目（第二次伤害）**照算** = **3** —— 消耗掉之后不再挡");
            Check(t.Health, hp0 - 3, "…这一次真掉血 6 → 3");
        }

        // ---- (3) 【灭自证·方向】**不带 dodge ⇒ 一点不跳**（与 (2) 同形状，只差那个关键词）----
        {
            UnitState a, b;
            var ctx = Duel(Unit("NoDodgeAtk", 1, 2, 9), Unit("NoDodgeDef", 1, 0, 6), out a, out b);
            var t = Board(ctx, 1, 3);
            CheckTrue(!t.Has(KeywordTable.Dodge), "（前提）目标**没有** dodge");
            Check(RuleCore.ApplyDamage(ctx, t, 3, "自检"), 3,
                  "★ 没有 dodge ⇒ 照常吃满 **3**（与 (2) 的 0 相反 —— 把 dodge 从结算侧删掉 (2) 必红）");
            Check(t.Health, 3, "…血量 6 → 3");
        }

        // ---- (4) **攻击路**：第 0 条落地的那个伤害段被跳、后面的照算 ----
        //  ⚠️ **次序按我们引擎 / 原版 `RecordAttackPendingDamage` 的登记次序**：星镖**先于**主伤害
        //     （原版 `BattleManager__RecordAttackPendingDamage.c:69-73` 先记 `CurrentShuriken`，
        //      `:80-84` 才记主伤害；我们 `DeclareAttack` 同序）。
        //  🔴 **2026-10-09（`A1107` 用户裁决）就地改的**：这一段原来写着
        //     「⛔ 与预览那条路（`ToggleCombatPreviewHighlight.c:62-71` 把**主伤害**放第 0 条）
        //       **次序不同** —— 那是原版自己的两处写法，如实记着，别去「统一」它们」——
        //     **现在已统一**：用户裁决**预览一律照这一套（真实落地）** ⇒
        //     `RuleCore.AttackDamageEntries` 现在也是 `[星镖, 主伤害+标记光]`，
        //     本组与 `TestWillDiePreviewEntries` 的 (b-2)/(b-3) 现在钉的是**同一个次序**。
        {
            UnitState a, b;
            var atk = Unit("DodgeAtk2", 1, 2, 9, "Shuriken 3");
            var ctx = Duel(atk, Unit("DodgeDef2", 1, 0, 7), out a, out b);
            var t = Board(ctx, 1, 3);
            t.AddKeyword(KeywordTable.Dodge, 1);
            Check(RuleCore.DeclareAttack(ctx, 0, 3, 1, 3), RuleCodes.OK, "（前提）攻击声明成功");
            Check(t.Health, 5, "★ 星镖 3（先落的第 0 条）被 Dodge 挡下、主伤害 2 照算 ⇒ 7 − 2 = **5**");
            CheckTrue(!t.Has(KeywordTable.Dodge), "…Dodge 被消耗掉了");
        }

        // ---- (5) **盾 + 闪避同时在身 ⇒ 一下把两条都消耗掉** ----
        //  原版那两段是**并列的 `if`**、不是 `else if`（`…MoveNext.c:320-325` 与 `:326-333`）。
        {
            UnitState a, b;
            var ctx = Duel(Unit("BothAtk", 1, 2, 9), Unit("BothDef", 1, 0, 6, "Shield"), out a, out b);
            var t = Board(ctx, 1, 3);
            t.AddKeyword(KeywordTable.Dodge, 1);
            CheckTrue(t.HasShield && t.Has(KeywordTable.Dodge), "（前提）同时带 Shield 与 Dodge");
            Check(RuleCore.ApplyDamage(ctx, t, 3, "自检"), 0, "挡下 = 0");
            CheckTrue(!t.HasShield, "★ Shield **被消耗**");
            CheckTrue(!t.Has(KeywordTable.Dodge), "★ Dodge **也被消耗** —— 两段是并列的 `if`");
            Check(t.Health, 6, "…血量没动");
        }

        // ---- (6) **回归：盾单独在身时行为没变**（本件动过 `ApplyDamage` 那一支的结构）----
        {
            UnitState a, b;
            var ctx = Duel(Unit("RegAtk2", 1, 2, 9), Unit("RegDef2", 1, 0, 4, "Shield"), out a, out b);
            var t = Board(ctx, 1, 3);
            Check(RuleCore.ApplyDamage(ctx, t, 3, "自检"), 0, "回归：盾挡下 = 0");
            CheckTrue(!t.HasShield, "…盾被消耗");
            Check(t.Health, 4, "…血量没动");
            Check(RuleCore.ApplyDamage(ctx, t, 3, "自检"), 3, "…第二下照吃 **3**");
        }

        // ---- (7) 【灭自证·**2026-10-09 换过口径**】**预览合计必须【等于】真打一局的实际掉血** ----
        //  🔴 旧版断言的是「预览 ≠ `DamageAfterReduction(整包)`」（3 vs 0）—— **那个基准是错的**：
        //     整包版是「**单次 `Hurt` 一个数**」的口径，而攻击落地是**两次** `Hurt`
        //     （星镖一次、主伤害一次）⇒ 整包版**根本不代表落地序列**，它给的 0 也不对。
        //  🔑 正确的不变量是「**预览 == 真打一局**」，而且它是**结构性的**：
        //     把 `AttackDamageEntries` 的次序改回 `[主伤害, 星镖]` ⇒ 预览变 0 + 3 = 3、
        //     而实际仍是 0 + 2 = 2 ⇒ 这条必红。⛔ 别再把整包版请回来当基准。
        {
            UnitState a, b;
            var atk = Unit("DodgeAtk3", 1, 2, 9, "Shuriken 3");
            var ctx = Duel(atk, Unit("DodgeDef3", 1, 0, 9), out a, out b);
            var t = Board(ctx, 1, 3);
            t.AddKeyword(KeywordTable.Dodge, 1);
            var entries = RuleCore.AttackDamageEntries(ctx, 0, 3, 1, 3, false);
            Check(entries.Count, 2, "（前提）预览条目 = **[星镖 3, 主伤害 2]**（落地次序）");
            int preview = RuleCore.DamageAfterReductionList(t, entries);
            Check(preview, 2, "★ 预览逐条：第 0 条 = **星镖 3** 被 dodge 跳掉 ⇒ 0 + 2 = **2**");
            int hp0 = t.Health;
            Check(RuleCore.DeclareAttack(ctx, 0, 3, 1, 3), RuleCodes.OK, "（前提）攻击声明成功");
            int landed = hp0 - t.Health;
            Check(landed, 2, "★ 落地实际掉血 = **2**（dodge 在星镖那一下被消耗、主伤害照落）");
            Check(preview, landed,
                  "★【灭自证】预览必须**等于**落地（预览 " + preview + " vs 落地 " + landed
                + "）—— 次序改回 [主伤害, 星镖] ⇒ 预览 3、落地 2 ⇒ 这里必红");
        }
    }

    /// <summary>
    /// **`Shield` 的两个表示收成一处**（2026-10-09 `A1106`，真缺陷）。
    ///
    /// **改前的病灶**：`Shield` 在引擎里曾有**两份表示** —— ① `UnitState.HasShield` 字段；
    /// ② 关键词 `_keywords["shield"]`。两个写点各只动一份 ⇒ **双向脱节**：
    ///   · 消耗时 `RuleCore.ApplyDamage` 只写 `u.HasShield = false`、**从不摘关键词**
    ///     （改前全仓 `RemoveAll("shield")` **0 命中**）⇒ `u.Has("shield")` 永远为真；
    ///     而 `SimpleAI.ScoreDamaging` 读的**正是关键词**
    ///     ⇒ **AI 把已经用掉盾的单位继续当带盾、只给 `dmg/3+1` 那点分**（表现层读字段、没事）；
    ///   · 反向：`RemoveAll("shield")`（`lose Shield` / 光环收回 / `RemoveKeyword` 减到 0）
    ///     **不清**那个字段 ⇒ 关键词没了、那一刻**还能再挡一下**（白送一次免伤）。
    ///
    /// **改法 = 照原版收成一处**（原版护盾**只有一个表示** = trait `0x50`：
    /// `DefinedTrait.shield = 80`，`d:/2/Warpforge_code/Scripts/Assembly-CSharp/DefinedTrait.cs:9`）：
    ///   · **免伤** `CardScript__GetAdjustedDamage.c:45` `HasCurrentTrait(param_1, 0x50)`；
    ///   · **消耗** `CardScript._ReceiveDamage_d__381__MoveNext.c:326-333` —— `HasCurrentTrait(0x50)`
    ///     → `RemoveBuffedTrait(0x50)` + `RemoveTrait(0x50)`（**摘 trait、不写任何布尔字段**；
    ///     `CardScript__RemoveTrait.c` 的实现是 `List.Find(id == param_2)` → `List.Remove`）；
    ///   · **对手 AI 也读 trait** `AI__ScoreFromDamagingBuffedUnit.c:58-61`（`0xf0`/`0x50` 命中即走那条出口）。
    ///   ⇒ 我们这边**关键词是唯一表示**，`UnitState.HasShield` 是它的**派生只读属性**。
    ///
    /// 🔴 **灭自证（改回旧写法必红）**：
    ///   ① 消耗之后再问 AI 要分 —— 旧写法下关键词没摘、永远停在 `3`（`dmg/3+1`），
    ///      所以「用掉后 == 正常路的 **9**」与「!= 3」两条**只有真摘了关键词才可能同时成立**；
    ///   ② 反向那一组（`RemoveAll` ⇒ `!HasShield`、随后**照常吃 3**）在字段版下必红。
    /// </summary>
    static void TestShieldOneRepresentation()
    {
        // ---- (1) **消耗（正方向）**：盾挡下 ⇒ 字段与关键词**同时**变假 ----
        {
            UnitState a, b;
            var ctx = Duel(Unit("ShAtk", 1, 2, 9), Unit("ShDef", 1, 0, 4, "Shield"), out a, out b);
            var t = Board(ctx, 1, 3);
            CheckTrue(t.HasShield && t.Has(KeywordTable.Shield),
                      "（前提）构造期两个表示就一致（`Shield` 关键词 ⇒ `HasShield`）");

            Check(RuleCore.ApplyDamage(ctx, t, 6, "自检"), 0, "盾把这一下全挡了（= 0）");
            Check(t.Health, 4, "…血量没动（不是「减到最低 1」）");
            CheckTrue(!t.Has(KeywordTable.Shield),
                      "★ 关键词被**摘掉**了（= 原版 `RemoveTrait(0x50)`；改前这里仍为真）");
            CheckTrue(!t.HasShield,
                      "★ 而且字段也是假 —— **两个表示不可能再脱节**（改前只写字段、关键词留着）");
        }

        // ---- (2) **AI 那一侧**：盾用掉之后，AI 不再把它当带盾 ----
        //  期望值写死：带盾出口 = `dmg/3 + 1` = 6/3 + 1 = **3**；
        //  正常路 = 「这一下判死」⇒ 卡价值 `4×2+1 = 9`（`ValueInPlay` 满分血、无别的关键词）⇒ **9**。
        {
            UnitState a, b;
            // ⚠️ 这张卡**自己不带** `Shield`（靠运行时 `AddKeyword` 给）—— 这样「用掉之后」的
            //    对照组就是「同一张卡、没给过盾」的干净版本，不会掺进 `KeywordValue(卡)` 那 2 分。
            var ctx = Duel(Unit("ShAtk2", 1, 2, 9), Unit("ShDef2", 4, 0, 4), out a, out b);
            var t = Board(ctx, 1, 3);
            t.AddKeyword(KeywordTable.Shield, 1);
            CheckTrue(t.HasShield && t.Has(KeywordTable.Shield), "（前提）运行时给了盾，两个表示都真");

            Check(SimpleAI.ScoreDamaging(t, 6), 3f,
                  "（前提）**还没用掉**时走原版那条「只给一点点」的出口 = 6/3 + 1 = **3**");

            Check(RuleCore.ApplyDamage(ctx, t, 6, "自检"), 0, "（前提）这一下被盾挡了、盾被用掉");
            CheckTrue(!t.HasShield && !t.Has(KeywordTable.Shield), "（前提）两个表示都变假");
            Check(t.Health, 4, "（前提）血没动（挡下了）");

            float after = SimpleAI.ScoreDamaging(t, 6);
            // 对照组：**同一张卡、从来没给过盾**的单位 ⇒ 必然走正常那条路
            var plain = new UnitState(Unit("ShDef2Plain", 4, 0, 4), false);
            Check(after, SimpleAI.ScoreDamaging(plain, 6),
                  "★ 用掉盾之后，AI 给的分与「从来没带盾的同形单位」**完全一样** —— 它已经走正常路了");
            Check(after, 9f,
                  "★ 那个分就是正常路算出来的 **9**（4 费卡价值 4×2+1 = 9；这一下 6 ≥ 4 血 ⇒ 判死那支）");
            Check(after != 3f, true,
                  "★【灭自证】旧写法会让它**停在 3**（关键词没摘 ⇒ 永远走带盾出口）—— 改回去这里必红");
        }

        // ---- (3) **反向**：关键词被摘掉 ⇒ 字段同时变假（`lose Shield` / 光环收回 / 减层到 0）----
        {
            UnitState a, b;
            var ctx = Duel(Unit("ShAtk3", 1, 2, 9), Unit("ShDef3", 1, 0, 5, "Shield"), out a, out b);
            var t = Board(ctx, 1, 3);
            CheckTrue(t.HasShield, "（前提）带盾");
            t.RemoveAll(KeywordTable.Shield);
            CheckTrue(!t.Has(KeywordTable.Shield) && !t.HasShield,
                      "★ `RemoveAll(\"shield\")` 之后**两个都**变假（改前：关键词没了、字段还是真）");
            Check(RuleCore.ApplyDamage(ctx, t, 3, "自检"), 3,
                  "★ …所以这一下**照常吃 3**（改前会被那个残留字段白送一次免伤）");
            Check(t.Health, 2, "…5 → 2");
        }
        {
            // 减层版（`lose Shield` 走的那条）：减到 0 ⇒ 走 `RemoveAll` ⇒ 属性跟着假
            var u = new UnitState(Unit("ShLose", 1, 0, 5, "Shield"), false);
            CheckTrue(u.HasShield, "（前提）带盾");
            u.RemoveKeyword(KeywordTable.Shield, 1);
            CheckTrue(!u.Has(KeywordTable.Shield) && !u.HasShield,
                      "★ `RemoveKeyword` 减到 0 之后属性也变假（`lose Shield` 那条路）");
        }

        // ---- (4) **没盾时不受影响**（本件动过 `ApplyDamage` 那一支的写法）----
        {
            UnitState a, b;
            var ctx = Duel(Unit("NoShAtk", 1, 2, 9), Unit("NoShDef", 4, 0, 4), out a, out b);
            var t = Board(ctx, 1, 3);
            CheckTrue(!t.HasShield && !t.Has(KeywordTable.Shield), "（前提）本来就没盾");
            Check(RuleCore.ApplyDamage(ctx, t, 3, "自检"), 3,
                  "★ 没盾 ⇒ 照常吃满 **3**（与 (1) 的 0 相反 —— 把「摘关键词」写成「无条件免伤」这里必红）");
            Check(t.Health, 1, "…4 → 1");
            // AI 那一侧同样不受影响
            var plain = new UnitState(Unit("NoShCtl", 4, 0, 4), false);
            Check(SimpleAI.ScoreDamaging(plain, 6), 9f,
                  "★ 没盾的单位在 AI 眼里照常走正常路 = **9**（不是带盾出口的 3）");
        }
    }

    static void TestHealAndDraw()
    {
        UnitState a, b;
        var medic = Unit("Medic", 2, 1, 4, "Ability: Heal 3 OwnWarlord");

        var ctx = Duel(medic, Unit("Dummy", 1, 0, 1), out a, out b);
        ctx.Players[0].Warlord.Health = 20;
        CheckCode(RuleCore.CanUseAbility(ctx, 0, 3), RuleCodes.OK, "治疗技能不用选目标");
        CheckCode(RuleCore.UseAbility(ctx, 0, 3), RuleCodes.OK, "放出来");
        Check(ctx.Players[0].Warlord.Health, 23, "督军 20 → 23");

        var ctx2 = Duel(medic, Unit("Dummy", 1, 0, 1), out a, out b);
        ctx2.Players[0].Warlord.Health = 29;
        CheckCode(RuleCore.UseAbility(ctx2, 0, 3), RuleCodes.OK, "血快满了也能放");
        Check(ctx2.Players[0].Warlord.Health, 30, "治疗封顶在最大生命 30（不是 32）");

        var scribe = Unit("Scribe", 2, 1, 4, "Ability: Draw 2");
        var ctx3 = Duel(scribe, Unit("Dummy", 1, 0, 1), out a, out b);
        int hand = ctx3.Players[0].Hand.Count;
        CheckCode(RuleCore.UseAbility(ctx3, 0, 3), RuleCodes.OK, "抽牌技能");
        Check(ctx3.Players[0].Hand.Count, hand + 2, "Draw 2 真抽了两张（不是只抽一张）");
    }

    /// <summary>
    /// 效果链的递归截断。
    /// 「受伤 → 打回去 → 那边也受伤 → 再打回来」天生是个环（规则书 :237 就在讲同时触发），
    /// 靠 `BattleContext.MaxEffectChain` 截断，不能指望「保证不会发生」。
    /// </summary>
    static void TestEffectChainGuard()
    {
        UnitState a, b;
        var p1 = Unit("PingPong", 1, 0, 30, "Penitence: Damage 1 EnemyUnit");
        var p2 = Unit("PingPong", 1, 0, 30, "Penitence: Damage 1 EnemyUnit");

        // Poker 放在槽 3，让「敌方最左的部队」落在 PingPong 上，环才转得起来
        var ctx = Duel(Unit("Poker", 1, 3, 9), p2, out a, out b, aSlot: 3, bSlot: 2);
        Place(ctx, 0, 2, p1);        // ⚠️ Poker 在 3 号格（`Duel(aSlot:3)`）⇒ 这里摆 2 号格
        ctx.ClearSignals();

        CheckCode(RuleCore.DeclareAttack(ctx, 0, 3, 1, 2), RuleCodes.OK, "点着这条链");

        int triggers = 0;
        foreach (var e in ctx.Signals) if (e.Kind == EvtKind.Trigger) triggers++;

        CheckTrue(triggers > 0, $"链真的转起来了（{triggers} 次触发）");
        CheckTrue(triggers <= BattleContext.MaxEffectChain,
                  $"被深度上限截断，没有无限递归（{triggers} ≤ {BattleContext.MaxEffectChain}）");
        Check(ctx.EffectChain, 0, "结算完深度回到 0（不然下一刀就少一层可用额度）");
        CheckTrue(Board(ctx, 0, 3).IsAlive && Board(ctx, 1, 2).IsAlive,
                  "两个乒乓单位都还活着（这条链是「互相点」，不是同归于尽）");
    }

    /// <summary>自己那套卡：效果文字**全部**解析得出来，六类关键词都有人用</summary>
    static void TestStarterCardEffects()
    {
        var all = StarterCards.Both();

        var unparsed = RuleCore.UnparsedEffects(all);
        Check(unparsed.Count, 0, "自己那套卡的效果文字全部解析得出来"
              + (unparsed.Count > 0 ? "（坏在这些：" + string.Join(" / ", unparsed) + "）" : ""));

        int withEffect = 0, withAbility = 0;
        foreach (var c in all)
        {
            if (c.Effects.Count > 0) withEffect++;
            if (c.HasAbility) withAbility++;
        }
        CheckTrue(withEffect >= 5, $"带触发效果的卡 {withEffect} 张（应 ≥ 5）");
        CheckTrue(withAbility >= 3, $"带主动技能的卡 {withAbility} 张（应 ≥ 3）");

        // 六类关键词**每一类都要有卡在用** —— 有一类没人用，它等于没做
        string[] need =
        {
            KeywordTable.Rally, KeywordTable.Strike, KeywordTable.Slay,
            KeywordTable.Backlash, KeywordTable.Penitence, KeywordTable.Ability,
        };
        foreach (var kw in need)
        {
            int n = 0;
            foreach (var c in all)
                if (kw == KeywordTable.Ability ? c.HasAbility : c.Effect(kw) != null) n++;
            CheckTrue(n > 0, $"「{kw}」至少有一张卡在用");
        }
        Debug.Log(P + $"   带效果的卡：触发 {withEffect} 张 / 技能 {withAbility} 张（共 {all.Count} 张）");
    }

    /// <summary>AI 会不会用技能 —— 不会用的话对局里永远看不到那类特效</summary>
    static void TestAiUsesAbility()
    {
        int s, t;

        // ① 治疗类：督军掉血就放，满血不浪费
        var guard = new CardDef("Reef Guard", "Reef Guard", "unit", "", null, "Test", 2, 0, 7, 0,
                                new[] { KeywordTable.Vanguard, "Ability: Heal 2 OwnWarlord" });
        var ctx = ToP2TurnWith(guard);
        CheckTrue(!SimpleAI.NextAbility(ctx, out s, out t), "督军满血 → 不浪费行动去治疗");

        ctx.Players[1].Warlord.Health -= 3;
        CheckTrue(SimpleAI.NextAbility(ctx, out s, out t), "督军掉血 → AI 会放治疗技能");
        Check(s, 3, "选中了场上的 Reef Guard");
        CheckCode(RuleCore.UseAbility(ctx, 1, s, t), RuleCodes.OK, "AI 挑的这一手真放得出来");

        // ② 伤害类：技能伤害 ≥ 攻击力就放 —— 技能不吃反击，没道理去平A
        var brute = new CardDef("Brute", "Brute", "unit", "", null, "Test", 3, 2, 5, 0,
                                new[] { "Ability: Damage 2 EnemyUnit" });
        var ctx2 = ToP2TurnWith(brute);
        Place(ctx2, 0, 3, Unit("Prey", 1, 0, 5));
        CheckTrue(SimpleAI.NextAbility(ctx2, out s, out t), "2 攻打 2 伤技能 → 放技能");
        Check(t, 3, "目标是对面那个单位");
        CheckCode(RuleCore.UseAbility(ctx2, 1, s, t), RuleCodes.OK, "放得出来");

        // ③ 攻击力更高 → 平A更划算
        var big = new CardDef("Big", "Big", "unit", "", null, "Test", 3, 9, 5, 0,
                              new[] { "Ability: Damage 2 EnemyUnit" });
        var ctx3 = ToP2TurnWith(big);
        Place(ctx3, 0, 3, Unit("Prey", 1, 0, 5));
        CheckTrue(!SimpleAI.NextAbility(ctx3, out s, out t), "9 攻打 2 伤技能 → 平A划算，不放技能");

        // ④ 对面场上没部队 → 伤害技能空过，不放
        var ctx4 = ToP2TurnWith(brute);
        CheckTrue(!SimpleAI.NextAbility(ctx4, out s, out t), "对面没有部队可打 → 不放（不白扔一次行动）");
    }

    /// <summary>造一个「轮到 P2 的第 1 回合，P2 槽 1 站着 card」的场景</summary>
    static BattleContext ToP2TurnWith(CardDef card)
    {
        var ctx = Battle(new[] { Unit("F1", 1, 1, 1), Unit("F2", 1, 1, 1), Unit("F3", 1, 1, 1) },
                         new[] { card, Unit("G1", 1, 1, 1), Unit("G2", 1, 1, 1) });
        ToP1Turn(ctx, 2);
        RuleCore.EndTurn(ctx);
        RuleCore.BeginTurn(ctx);          // 轮到 P2
        Place(ctx, 1, 3, card);
        return ctx;
    }

    /// <summary>
    /// **对手 AI 照原版重写**（2026-09-17）—— 把从反编译里读出来的规则逐条钉住。
    /// 正本：`资料/AI_原版反编译_0917.md`（公式 · 常量 · 数据类 · **死代码清单**都在那儿）。
    /// </summary>
    static void TestAiOriginal()
    {
        // ① 换牌规则（原版 `AI.GetAiMulliganCards`）：`manaCost > 4` 换掉、其余保留
        {
            var ctx = RuleCore.NewBattle(
                Deck(Unit("a", 1, 1, 1)),
                Deck(Unit("Cheap", 1, 1, 1), Unit("Dear", 6, 6, 6), Unit("Mid", 4, 2, 2)),
                seed: 0, shuffle: false, openMulligan: true);
            var idx = SimpleAI.AiMulliganIndices(ctx, 1);
            Check(idx.Count, 1, "★ 只换「费用 > 4」的那张（原版 `manaCost > 4`）");
            Check(idx[0], 1, "★ 换的正是手牌里那张 6 费（下标 1）");
        }

        // ② 卡价值 = 费用 × 2 + 1（原版 `GetCardReferenceValueInPlay`）—— 所有分曲线的尺子
        Check(SimpleAI.RefValue(Unit("X", 3, 1, 1)), 7f, "★ 卡价值 = 费用 × 2 + 1");

        // ③ 打督军：够斩杀 = 压倒性分；非致命 = 伤害 × 1.8（剩余血 ≤ 15）
        {
            var ctx = ToP2TurnWith(Unit("Brute", 3, 3, 5));
            var w = ctx.Players[0].Warlord;
            w.Health = 3;
            CheckTrue(SimpleAI.ScoreWarlordDamage(w, 3) >= 1000000f,
                      "★ 这一下打死督军 → 压倒性分（原版 1e6）");
            w.Health = 10;
            float got = SimpleAI.ScoreWarlordDamage(w, 3);
            CheckTrue(Math.Abs(got - 3f * 1.8f) < 0.001f,
                      $"★ 非致命打督军 = 伤害 × 1.8（剩余血 ≤ 15），实得 {got}");
        }

        // ④ 合击斩杀上界：各单位**取自己最高的那一刀**、再相加（原版 `CombinedAttackCanKillWarlord`）
        {
            var ctx = ToP2TurnWith(Unit("A", 2, 2, 2));
            ctx.Players[1].Warlord.Exhausted = true;      // ⚠️ 督军也算攻击者 —— 先疲劳掉再量（踩过）
            Place(ctx, 1, 2, Unit("B", 2, 2, 2));       // ⚠️ 3 号格已经被 `ToP2TurnWith` 摆上了
            ctx.Players[0].Warlord.Health = 4;
            Check(SimpleAI.DamageToFoeWarlord(ctx), 4, "★ 合击上界 = 2 + 2（两支部队各自的刀相加）");
            CheckTrue(SimpleAI.CanLethal(ctx), "★ 攒够 4 点 → 判得出斩杀线");

            ctx.Players[0].Warlord.Health = 5;
            CheckTrue(!SimpleAI.CanLethal(ctx), "★ 差 1 点就不算斩杀（边界卡死）");
        }

        // ⑤ 选择：平手保留**先出现的**（原版严格 `>`）；分 ≤ 0 就宁可收手（`endTurn` 基准 0）
        {
            var ctx = ToP2TurnWith(Unit("A", 2, 2, 2));
            var l = new List<AiAction> {
                new AiAction { Kind = AiActionKind.PlayCard, HandIdx = 0, Score = 5f },
                new AiAction { Kind = AiActionKind.PlayCard, HandIdx = 1, Score = 5f },
                new AiAction { Kind = AiActionKind.EndTurn },
            };
            Check(SimpleAI.SelectBestAction(ctx, l).HandIdx, 0, "★ 平手时保留**先出现**的那条（严格 `>`）");

            var l2 = new List<AiAction> {
                new AiAction { Kind = AiActionKind.PlayCard, HandIdx = 0, Score = -1f },
                new AiAction { Kind = AiActionKind.EndTurn },
            };
            CheckTrue(SimpleAI.SelectBestAction(ctx, l2).Kind == AiActionKind.EndTurn,
                      "★ 分 ≤ 0 就不做 —— 原版的「留牌」就写在这条基准上");
        }

        // ⑥ 难度旋钮（原版 `TweakAvailableActions`）：困难档一条都不砍；很简单档一定砍最低分的
        {
            Check(SimpleAI.KnobsOf(AiDifficulty.Hard).MaxSkips, 0, "★ 困难档不砍任何动作");
            CheckTrue(SimpleAI.KnobsOf(AiDifficulty.SuperEasy).MaxSkips > 0,
                      "★ 很简单档会砍掉最低分的那些动作");

            // 同一 seed 的两个局面 ⇒ 砍掉的条数一致（骰子走 `ctx.AiRng`，一局必须可复现）
            var c1 = ToP2TurnWith(Unit("A", 2, 2, 2));
            var c2 = ToP2TurnWith(Unit("A", 2, 2, 2));
            var l1 = SimpleAI.EnumerateActions(c1);
            foreach (var a in l1) a.Score = SimpleAI.ScoreAction(c1, a);
            var l2 = SimpleAI.EnumerateActions(c2);
            foreach (var a in l2) a.Score = SimpleAI.ScoreAction(c2, a);
            int n1 = l1.Count;
            Check(n1, l2.Count, "同 seed 的两个局面，动作表一样大");
            SimpleAI.TweakAvailableActions(c1, l1, AiDifficulty.SuperEasy);
            SimpleAI.TweakAvailableActions(c2, l2, AiDifficulty.SuperEasy);
            Check(l1.Count, l2.Count, "★ 同 seed ⇒ 砍掉的条数一致（可复现）");
            CheckTrue(l1.Count < n1, "★ 很简单档确实砍掉了动作（不是空转）");
        }

        // ⑦ 动作表覆盖：**替代行动**进表 —— 老实现里 AI 一条都不走（这些卡在它手上等于死的）
        {
            var dut = new CardDef("DutyMan", "DutyMan", "unit", "Duty: Deal 3 damage to an enemy troop",
                                  null, "Test", 2, 2, 3, 0, new[] { KeywordTable.Duty });
            var ctx = ToP2TurnWith(dut);
            Place(ctx, 0, 3, Unit("Prey", 1, 1, 3));
            bool hasDuty = false, hasAttack = false;
            foreach (var a in SimpleAI.EnumerateActions(ctx))
            {
                if (a.AltKeyword == KeywordTable.Duty) hasDuty = true;
                if (a.Kind == AiActionKind.AttackMelee) hasAttack = true;
            }
            CheckTrue(hasDuty, "★ `duty` 替代行动进了动作表（原来 AI 完全不碰这一族）");
            CheckTrue(hasAttack, "近战攻击也在表里（近战/远程各一条）");
        }

        // ⑧ 🆕 收集灵魂石进动作表（原版动作表第 4 支 `clickWaystone`，**固定 50 分**；2026-09-25 接上）
        //    ⚠️ 这一条钉的是**一个很容易写错、而且静默**的地方：残骸恒为 `Exhausted`，
        //       若把收集塞进那个「跳过 `Exhausted`」的单位循环里，**一条动作都产不出来**，
        //       AI 永远不收石头，而没有任何报错。
        {
            var ctx = ToP2TurnWith(Unit("W", 2, 2, 3));
            var st = Place(ctx, 1, 3, Unit("AS", 1, 1, 1, KeywordTable.Waystone));
            st.IsRemnant = true;
            st.Health = 1;

            bool hasCollect = false; float score = -1f;
            foreach (var a in SimpleAI.EnumerateActions(ctx))
                if (a.Kind == AiActionKind.CollectWaystone)
                { hasCollect = true; score = SimpleAI.ScoreAction(ctx, a); }

            CheckTrue(hasCollect, "★ 收集灵魂石**进了动作表**（原版 `clickWaystone` 是独立一支，"
                                + "不受 `Exhausted` 影响）");
            Check(score, 50f, "★ 它的分是原版的**固定 50.0**（不看局势、不算目标）");

            int before = ctx.Players[1].SpiritStones;
            CheckTrue(SimpleAI.ExecuteAction(ctx, new AiAction { Kind = AiActionKind.CollectWaystone, Slot = 3 }),
                      "★ AI 真的去收集了");
            Check(ctx.Players[1].SpiritStones, before + 1, "★ 收完灵魂石 +1");
            CheckTrue(ctx.Players[1].Board[3] == null, "★ 那颗灵魂石从棋盘上没了");
        }

        // ⑨ 🆕 2026-09-29（Q5）：**放位照原版** —— AI **不选格位**，格位由
        //    `MinionManager.GetNextSlotCheckingAdjacents()` 定（判据只在 `SimpleAI.NextDeploySlot` 一处）。
        //    空场序列必须是 **右近 → 左近 → 右次 → 左次**（原版「两侧相等 ⇒ 先右」）。
        //    🔴 老实现是「逐格枚举 + 打分挑最小槽号」⇒ 永远先把**左边 4 格从外往里**填满，**方向正好相反**。
        {
            var ctx = Battle(new[] { Unit("F1", 1, 1, 1) }, new[] { Unit("F2", 1, 1, 1) });
            ToP1Turn(ctx, 2);
            RuleCore.EndTurn(ctx); RuleCore.BeginTurn(ctx);      // 轮到索引 1
            Check(ctx.Active, 1, "夹具：轮到 P2（索引 1）" + LogTail(ctx));

            int W = BoardSpec.WarlordSlot;
            Check(SimpleAI.NextDeploySlot(ctx, 1), W + 1,
                  "★ 空场第一只落【右侧最近】那格（原版两侧相等 ⇒ 先右）");
            Place(ctx, 1, W + 1, Unit("A", 1, 1, 1));
            Check(SimpleAI.NextDeploySlot(ctx, 1), W - 1, "★ 第二只落【左侧最近】");
            Place(ctx, 1, W - 1, Unit("B", 1, 1, 1));
            Check(SimpleAI.NextDeploySlot(ctx, 1), W + 2, "★ 第三只落右侧第二格");
            Place(ctx, 1, W + 2, Unit("C", 1, 1, 1));
            Check(SimpleAI.NextDeploySlot(ctx, 1), W - 2, "★ 第四只落左侧第二格");

            // 🔴 反面：老实现「永远最小槽号」会落在**最左边那格 0**（= 距督军最远）
            CheckTrue(SimpleAI.NextDeploySlot(ctx, 1) != 0,
                      "★ 不是老实现的「永远最小槽号」（那会落最左那格 0，方向正好相反）");

            // 该侧满 4 只 ⇒ 只能去另一侧（原版 `slotPos.Count − minions.Count < 1`）
            for (int i = 1; i <= BoardSpec.SlotsPerSide; i++)
                if (ctx.Players[1].Board[W + i] == null) Place(ctx, 1, W + i, Unit("R" + i, 1, 1, 1));
            CheckTrue(SimpleAI.NextDeploySlot(ctx, 1) < W,
                      "★ 右侧满 4 只 ⇒ 只能落到左侧（不会算出越界的槽号）");
        }

        // ⑩ 🆕 「**贴着带相邻效果的单位放**」—— 原版那条特判，**优先于**平衡规则。
        {
            var aura = new CardDef("AuraMan", "AuraMan", "unit", "Adjacent units have Armour 1",
                                   null, "Test", 1, 1, 1, 0, null);
            CheckTrue(SimpleAI.HasAdjacentEffect(aura),
                      "★ 认得「带相邻效果」的卡（我们这边 = `AuraSpec.Adjacent`；"
                    + "原版判据 = `HasWhileInPlayAdjacentEffect`，`requiem` 那一支全池 0 命中）");
            CheckTrue(!SimpleAI.HasAdjacentEffect(Unit("Plain", 1, 1, 1)),
                      "反面：普通小兵不算（不然这条特判会天天触发、平衡规则永远轮不到）");

            var ctx = Battle(new[] { Unit("F1", 1, 1, 1) }, new[] { Unit("F2", 1, 1, 1) });
            ToP1Turn(ctx, 2);
            RuleCore.EndTurn(ctx); RuleCore.BeginTurn(ctx);
            int W = BoardSpec.WarlordSlot;
            // 左侧最靠督军那格站一个带光环的 ⇒ 下一只该**贴着它外侧**（W−2），
            // 而不是按平衡规则落右侧（那时左 1 右 0，平衡会选**左**…… 所以要挑个平衡会选右的局面）
            Place(ctx, 1, W - 1, aura);
            Place(ctx, 1, W + 1, Unit("R", 1, 1, 1));
            Place(ctx, 1, W + 2, Unit("R2", 1, 1, 1));   // 左 1 / 右 2 ⇒ 平衡会选【左】
            Check(SimpleAI.NextDeploySlot(ctx, 1), W - 2,
                  "★ 贴着带相邻效果的单位放（这条**优先于**平衡规则）");
            CheckTrue(SimpleAI.NextDeploySlot(ctx, 1) != W - 1, "反面：不会算到**已占**的那一格上");
        }

        // ⑪ 🆕 2026-09-29（Q6）：**战术卡要挑对目标** —— 同一张卡打不同目标**必须不同分**。
        //    🔴 老实现里 `ScoreOp` 的 `slot` 形参**一次都没读** ⇒ 同一张卡所有格位**同分**、
        //       平手留先（严格 `>`）⇒ **永远打「槽号最小的合法目标」**；
        //       后果是**裸 `Deal N damage` 不会打最低血的那个**。
        //    原版判据：`AI__ScoreFromPlayingNow.c` 拿 `param_4`（=这条动作的**目标**）去
        //    `FilterMethods.CheckIfMeetsCriteria` 逐条筛 ⇒ 目标参与打分。
        {
            var ctx = Battle(new[] { Unit("F1", 1, 1, 1) }, new[] { Unit("F2", 1, 1, 1) });
            ToP1Turn(ctx, 2);
            RuleCore.EndTurn(ctx); RuleCore.BeginTurn(ctx);      // 轮到索引 1
            int W = BoardSpec.WarlordSlot;
            Place(ctx, 0, W + 1, Unit("Tank", 1, 1, 9));         // 槽号更小、血多（2 伤打不死）
            Place(ctx, 0, W + 2, Unit("Squishy", 1, 1, 1));      // 槽号更大、一刀能打死

            var zap = Tactic("Zap", 1, "Deal 2 damage to an enemy troop");
            var inst = ctx.NewInstance(zap);
            var aSmall = new AiAction { Kind = AiActionKind.PlayCard, HandInst = inst, Slot = W + 1 };
            var aBig = new AiAction { Kind = AiActionKind.PlayCard, HandInst = inst, Slot = W + 2 };

            float sSmall = SimpleAI.ScoreAction(ctx, aSmall);
            float sBig = SimpleAI.ScoreAction(ctx, aBig);
            CheckTrue(sBig > sSmall,
                      $"★ 同一张「2 点伤害」打【能打死的那只】分更高（{sBig} > {sSmall}）"
                    + " —— 老实现里两格同分 ⇒ 永远打槽号小的那个");

            // 🔴 反面：`slotIsTarget: false`（= 落点不是目标，比如小兵）时两格**必须同分**
            //    —— 钉住「这层只在『目标已选定』那条路上生效」，别让它污染小兵的打分。
            var ops = EffectText.WillRunOps(zap);
            Check(SimpleAI.ScoreOps(ctx, ops, W + 1, false), SimpleAI.ScoreOps(ctx, ops, W + 2, false),
                  "反面：不是目标时不参与打分（小兵的落点不该影响它的效果分）");
        }

        // ⑫ 🆕 2026-09-29（Q6 后半段）：**引擎拒绝 ⇒ 退次优**，不是一拒就收手。
        //    原版（我们照抄的形状）是 `break`；用户 2026-09-29 点名要改。
        {
            var ctx = ToP2TurnWith(Unit("A", 1, 1, 1));
            AiAction first;
            CheckTrue(SimpleAI.NextAction(ctx, AiDifficulty.Hard, out first), "先挑出一条最好的");

            var excl = new List<AiAction> { first };
            AiAction second;
            bool got = SimpleAI.NextAction(ctx, AiDifficulty.Hard, excl, out second);
            CheckTrue(got, "★ 把第一条排除掉之后**还剩别的能做**（这就是「退次优」）");
            CheckTrue(second != null && !(second.Kind == first.Kind && second.HandIdx == first.HandIdx
                                       && second.Slot == first.Slot && second.TargetSlot == first.TargetSlot),
                      "★ 挑出来的是**另一条**，不是原来那条（排除名单生效）");

            // 反向：不传排除名单 ⇒ 还是同一条（证明上面那条差异是排除造成的，不是局面变了）
            AiAction again;
            CheckTrue(SimpleAI.NextAction(ctx, AiDifficulty.Hard, out again), "再挑一次");
            CheckTrue(again.Kind == first.Kind && again.Slot == first.Slot
                      && again.HandIdx == first.HandIdx && again.TargetSlot == first.TargetSlot,
                      "不传排除名单时挑的还是同一条（同局面 ⇒ 可复现）");
        }
    }

    /// <summary>
    /// `SimpleAI` 的**斩杀线**（2026-09-17）：这一回合总伤害够打死对面督军时，
    /// 必须**直接打脸**，不许去清部队。
    ///
    /// 🔴 这是一条**回归测试**，钉的是一个真会送掉胜局的 bug：原来评分里
    ///    「打死一个部队」= **1000** 分、「打督军脸」= **400** 分 ⇒
    ///    对面督军剩 5 血、我这三个 3/3 一刀就能砍死他的时候，
    ///    AI **会先去清那个 9 血诱饵**。修法见 `SimpleAI.CanLethal` / `NextAttack` 的注释。
    /// </summary>
    static void TestAiKillLine()
    {
        int a, tp, ts; bool ranged;

        // ---- ① 正面：3 个 3/3 够打死 5 血督军 ⇒ 这一刀必须打脸 ----
        var ctx = ToP2TurnWith(Unit("Mine0", 1, 3, 3));
        Place(ctx, 1, 2, Unit("Mine1", 1, 3, 3));   // ⚠️ 3 号格已经被 `ToP2TurnWith` 摆上了
        Place(ctx, 1, 5, Unit("Mine2", 1, 3, 3));
        ctx.Players[0].Warlord.Health = 5;              // 对面督军剩 5
        Place(ctx, 0, 3, Unit("Prey", 1, 1, 9));        // 一个**打不死**的诱饵（9 血）
        // ⚠️ **督军自己也是攻击者**（它就在槽 `BoardSpec.WarlordSlot`，`NextAttack` 一直把它算在内）
        //    ⇒ 是 3×3 + 2 = **11**，不是 9。这条断言顺带把「督军算一个攻击者」钉下来
        //    —— 第一版这里写的是 9，被这条断言当场打了回来。
        Check(SimpleAI.DamageToFoeWarlord(ctx), 11,
              "★ 这一回合能对督军打出的总伤害 = 3×3 + **督军自身 2 攻**" + LogTail(ctx));
        CheckTrue(SimpleAI.CanLethal(ctx), "★ 判得出斩杀线（11 ≥ 5）");
        CheckTrue(SimpleAI.NextAttack(ctx, out a, out tp, out ts, out ranged), "AI 挑得出一刀");
        Check(tp, 0, "★ 这一刀打的是对面那一方");
        Check(ts, BoardSpec.WarlordSlot,
              "★ 目标是**督军格**，不是那个 9 血诱饵（旧评分里「清部队 1000 > 打脸 400」会去清诱饵）");
        CheckCode(RuleCore.DeclareAttack(ctx, 1, a, tp, ts, ranged), RuleCodes.OK,
                  "AI 挑的这一手引擎认（别让它挑一手打不出的刀）");

        // ---- ② 反例：差 1 点就不算斩杀（9 < 10）----
        var ctx2 = ToP2TurnWith(Unit("Mine0", 1, 3, 3));
        Place(ctx2, 1, 2, Unit("Mine1", 1, 3, 3));   // ⚠️ 3 号格已经被 `ToP2TurnWith` 摆上了
        Place(ctx2, 1, 5, Unit("Mine2", 1, 3, 3));
        ctx2.Players[0].Warlord.Health = 12;
        CheckTrue(!SimpleAI.CanLethal(ctx2), "★ 差 1 点（11 < 12）就不算斩杀 —— 别把「差不多」当斩杀");
        ctx2.Players[0].Warlord.Health = 11;
        CheckTrue(SimpleAI.CanLethal(ctx2), "★ 刚好够（11 = 11）就算 —— **边界要卡死**");

        // ---- ③ 一个单位**只算一刀**：近战 2 / 远程 5 只贡献 5 ----
        // ⚠️ 把督军先疲劳掉，这条才量得准（不排掉的话它是 5 + 2 = 7，看不出是不是两路相加 ——
        //    第一版就是这么被打了回来的）
        var ctx3 = ToP2TurnWith(Ranged("Shooter", 2, 2, 3, 5));
        ctx3.Players[1].Board[BoardSpec.WarlordSlot].Exhausted = true;
        Check(SimpleAI.DamageToFoeWarlord(ctx3), 5,
              "★ 近战 2 / 远程 5 的单位只算**高的那一路**（两路相加的话这里是 7）");

        // ---- ④ 疲劳的单位打不了 ⇒ 不算进斩杀线 ----
        var ctx4 = ToP2TurnWith(Unit("Tired", 1, 4, 4));
        ctx4.Players[1].Board[BoardSpec.WarlordSlot].Exhausted = true;   // 同样先排掉督军
        Check(SimpleAI.DamageToFoeWarlord(ctx4), 4, "★ 对照组：没疲劳时它算 4 点");
        ctx4.Players[1].Board[3].Exhausted = true;
        Check(SimpleAI.DamageToFoeWarlord(ctx4), 0, "★ 疲劳的单位不算进斩杀线");

        // ---- ⑤ 🆕「能一击打死就优先打**价值最高**那个」（2026-09-25：用户问的那条）----
        //    它是**打分层涌现**出来的，**不是**选目标层的一条分支（原版 `TargetSelectMethod` 那 8 档里
        //    根本没有「攻击力最低」）。原版 `ScoreFromDamagingBuffedUnit`：
        //      · 打死 → `价值 × 1.0`（带 `survivor` 打 0.8）
        //      · 打不死 → `价值 × 0.6 × 伤害 / 血上限`
        //    我们那两支在 `SimpleAI.MinionScore` / `WarlordDamageScore`（数值逐条照原版）。
        //    判据 → `资料/AI_原版反编译_0917.md` §十·6。
        //    ⚠️ **假想敌的攻击力全给 0**，把「反击分」那一项摘掉，只留「打谁」这一项；
        //       ⚠️ 还要**挑过督军那一项**（打不死督军 = `伤害 × 1.2` = 6 分），
        //       所以下面两个小兵的价值都取到 6 以上，不然 AI 会去蹭脸。
        {
            var c5 = ToP2TurnWith(Unit("Striker", 1, 5, 5));         // 我的一刀 5 攻
            c5.Players[1].Board[BoardSpec.WarlordSlot].Exhausted = true;    // 排掉督军，只比这一刀
            Place(c5, 0, 2, Unit("Cheap", 3, 0, 3));                 // 价值 7、能杀
            Place(c5, 0, 3, Unit("Dear", 6, 0, 5));                  // 价值 13、也能杀
            CheckTrue(SimpleAI.NextAttack(c5, out a, out tp, out ts, out ranged), "⑤ AI 挑得出一刀");
            Check(ts, 3, "★ **两个都能一刀打死时，打价值高那个**（打死给 `价值 × 1.0`）" + LogTail(c5));

            // 反例：那口**打不死**的别去碰 —— 打不死只有 `价值 × 0.6 × 伤害/血` 分
            var c5b = ToP2TurnWith(Unit("Striker", 1, 5, 5));
            c5b.Players[1].Board[BoardSpec.WarlordSlot].Exhausted = true;
            Place(c5b, 0, 2, Unit("Snack", 3, 0, 3));                // 价值 7、能杀 ⇒ 7 分
            Place(c5b, 0, 3, Unit("Tank", 8, 0, 20));                // 价值 17，但只能打 5/20 ⇒ 2.55 分
            c5b.Players[0].Warlord.Health = 40;                      // 打脸只有 6 分（40-5 > 15 ⇒ ×1.2）
            CheckTrue(SimpleAI.NextAttack(c5b, out a, out tp, out ts, out ranged), "⑤ 反例：AI 挑得出一刀");
            Check(ts, 2, "★ **打不死的那口先不碰** —— 去打能杀掉的（`价值 × 0.6 × 伤害/血` 打不过击杀分）"
                       + LogTail(c5b));
        }
    }

    /// <summary>
    /// 事件流的**确定性**：同种子必须逐条一致。
    /// 事件流是表现层放特效的依据 —— 它要是不可复现，特效的 bug 就没法查。
    /// </summary>
    static void TestSignalDeterminism()
    {
        var a = RunScriptedGame(20260911);
        var b = RunScriptedGame(20260911);
        Check(a.Count, b.Count, $"同种子 → 事件条数一致（{a.Count} 条）");

        bool same = a.Count == b.Count;
        for (int i = 0; same && i < a.Count; i++) same = a[i] == b[i];
        CheckTrue(same, "同种子 → 事件流逐条一致");

        var c = RunScriptedGame(777);
        bool differs = c.Count != a.Count;
        for (int i = 0; !differs && i < c.Count; i++) differs = c[i] != a[i];
        CheckTrue(differs, "换种子 → 事件流不一样（证明随机真的在起作用）");

        // 这两类事件**必须真的出现在对局里** —— 不然「接上了」只是纸上谈兵。
        // 跑满 40 回合（牌库抽空就靠疲劳收场），30 张的牌库足够把带效果的卡都摸到
        bool sawAbility = false, sawTrigger = false;
        foreach (var line in a)
        {
            if (line.Contains("Ability")) sawAbility = true;
            if (line.Contains("Trigger")) sawTrigger = true;
        }
        CheckTrue(sawAbility, $"这段脚本对局里出现了 Ability 事件（部队卡发动技能）");
        CheckTrue(sawTrigger, $"这段脚本对局里出现了 Trigger 事件（触发效果）");

        // 事件种类分布 —— 「怎么一条 Ability 都没有」这种问题一眼能看见
        var kinds = new SortedDictionary<string, int>(StringComparer.Ordinal);
        foreach (var line in a)
        {
            var sp = line.Split(' ');
            if (sp.Length < 2) continue;
            int n;
            kinds.TryGetValue(sp[1], out n);
            kinds[sp[1]] = n + 1;
        }
        var parts = new List<string>();
        foreach (var kv in kinds) parts.Add($"{kv.Key}×{kv.Value}");
        Debug.Log(P + $"   事件流 {a.Count} 条：" + string.Join("  ", parts));
    }

    /// <summary>
    /// 跑一段固定脚本的对局，把事件流原样收下来做字符串（好比较）。
    ///
    /// ⚠️ **督军的血被调大了** —— 这一段的目的不是「打完一局分出胜负」
    ///    （那是 <see cref="TestFullGameWithRealCards"/> 的事），而是**跑够回合数**，
    ///    让 30 张牌库里那些带效果的卡都上过场。真实长度的对局十几回合就结束了，
    ///    那点回合数里摸不摸得到 Ironclad / Reef Guard 全看运气，断言会飘。
    /// </summary>
    static List<string> RunScriptedGame(int seed, int turns = 40)
    {
        var ctx = RuleCore.NewBattle(
            DeckBuilder.StarterDeck(StarterCards.Ember(), StarterCards.EmberFaction, 30, new System.Random(1)),
            DeckBuilder.StarterDeck(StarterCards.Tide(), StarterCards.TideFaction, 30, new System.Random(2)),
            seed);

        for (int i = 0; i < 2; i++)
        {
            ctx.Players[i].Warlord.MaxHealth = 999;
            ctx.Players[i].Warlord.Health = 999;
        }

        for (int i = 0; i < turns && !ctx.IsOver; i++)
        {
            RuleCore.BeginTurn(ctx);
            SimpleAI.PlayTurn(ctx);
            if (ctx.IsOver) break;
            RuleCore.EndTurn(ctx);
        }

        var log = new List<string>();
        foreach (var e in ctx.Signals) log.Add(e.ToString());
        return log;
    }

    // ==================================================================
    //  胜负与疲劳
    // ==================================================================

    static void TestWinnerByWarlord()
    {
        var ctx = Battle(new[] { Unit("A", 1, 40, 40), Unit("F1", 1, 1, 1), Unit("F2", 1, 1, 1) },
                         new[] { Unit("X", 1, 1, 1), Unit("Y", 1, 1, 1), Unit("Z", 1, 1, 1) });
        ToP1Turn(ctx, 3);
        Place(ctx, 0, 3, Unit("A", 1, 40, 40));

        Check(RuleCore.CheckWinner(ctx), 0, "开局进行中");
        CheckCode(RuleCore.DeclareAttack(ctx, 0, 3, 1, BoardSpec.WarlordSlot), RuleCodes.OK,
                  "可以攻击敌方督军");
        Check(ctx.Winner, 1, "督军被打死 → P1 胜");
        Check(RuleCore.CheckWinner(ctx), 1, "重复调用 CheckWinner 结果稳定");

        // 不能打自己的督军
        var ctx2 = Battle(new[] { Unit("A", 1, 1, 1), Unit("F1", 1, 1, 1), Unit("F2", 1, 1, 1) },
                          new[] { Unit("X", 1, 1, 1), Unit("Y", 1, 1, 1), Unit("Z", 1, 1, 1) });
        ToP1Turn(ctx2, 3);
        Place(ctx2, 0, 3, Unit("A", 1, 1, 1));
        CheckCode(RuleCore.DeclareAttack(ctx2, 0, 3, 0, BoardSpec.WarlordSlot), RuleCodes.ErrSelf,
                  "不能攻击自己场上的督军");
    }

    /// <summary>
    /// 投降（原版 `BattleResult.Forfeit`）。**这条以前完全没有** —— 用户 2026-09-12 点名要还原。
    /// 判据有三条：① 立刻判对方胜（**不看血量**）② 记下是谁投的 ③ 判过了不再改。
    /// </summary>
    static void TestForfeit()
    {
        var ctx = Battle(new[] { Unit("A", 1, 40, 40), Unit("F1", 1, 1, 1), Unit("F2", 1, 1, 1) },
                         new[] { Unit("X", 1, 1, 1), Unit("Y", 1, 1, 1), Unit("Z", 1, 1, 1) });
        ToP1Turn(ctx, 3);
        Check(ctx.Winner, 0, "开局进行中（谁都没倒）");
        Check(ctx.ForfeitedBy, -1, "还没人投降");

        // P0 投降 → P1（2 号）胜
        Check(RuleCore.Forfeit(ctx, 0), 2, "P0 投降 → P1 胜（**不看督军血量**）");
        Check(ctx.ForfeitedBy, 0, "记下是谁投的");
        CheckTrue(ctx.Players[0].Warlord.Health > 0, "投的时候督军还活着（不是被打死的）");
        CheckTrue(ctx.Events[ctx.Events.Count - 1].Contains("投降"), "事件日志里写明了投降");

        // 已经结束了：第二次投降（连同对方的）都不作数
        Check(RuleCore.Forfeit(ctx, 1), 2, "判过之后再投降不改结果");
        Check(ctx.ForfeitedBy, 0, "也不改「谁投的」");

        // 另一条路：P1 投降 → P0 胜
        var ctx2 = Battle(new[] { Unit("A", 1, 1, 1), Unit("F1", 1, 1, 1), Unit("F2", 1, 1, 1) },
                          new[] { Unit("X", 1, 1, 1), Unit("Y", 1, 1, 1), Unit("Z", 1, 1, 1) });
        Check(RuleCore.Forfeit(ctx2, 1), 1, "P1 投降 → P0 胜");
        Check(ctx2.IsOver, true, "投降之后 `IsOver` 为真");

        // 越界/无效参数：什么都不做（**不能静默判错**）
        var ctx3 = Battle(new[] { Unit("A", 1, 1, 1), Unit("F1", 1, 1, 1), Unit("F2", 1, 1, 1) },
                          new[] { Unit("X", 1, 1, 1), Unit("Y", 1, 1, 1), Unit("Z", 1, 1, 1) });
        Check(RuleCore.Forfeit(ctx3, 7), 0, "非法玩家号 → 返回 0、不改状态");
        Check(ctx3.Winner, 0, "…结果也还是「进行中」");

        // ------------------------------------------------------------
        //  🆕 2026-10-18（**A913**）：**理由码** —— 原版
        //     `BattleManager.DeadHero(bool isPlayerDying, BattleResult battleResult)` 的**第二个实参**。
        //  判据：取值表 `d:/2/Warpforge_code/Scripts/Assembly-CSharp/BattleResult.cs`（7 个值，逐值见
        //  `RuleEngine.BattleResult`）；13 个调用点逐条现读 → `资料/普查产出_1018/R3_联机三档现核.md` §2·1。
        //  🔴 它在本工程里的**唯一落点** = `ctx.Events` 上那一行 `[BattleResult] …` token
        //     （码**不过网、不进制指纹、不进任何状态** —— 主对话 2026-10-18 已裁，理由是零回放风险；
        //      原版本身也「不过网」：`BattleCommsManager.SendForfeit` 发的是空参数表）。
        //  ⚠️ 下面一律认那个 **token**，⛔ 不认中文措辞（措辞会改、翻译会改 ⇒ 那就是
        //     「拿给人看的句子当逻辑」—— 本批已经栽过四次的模式）。
        //  🧨 **判别式**：把 `Forfeit` 里那句 token 的 `{reason}` 换成写死的 `BattleResult.Forfeit`
        //     ⇒ **A 组与 D 组同时红**（B、C 照绿）；把形参默认值改掉 ⇒ **C 组红**。
        //     这就是为什么要 A / B **正负成对**、并把 `Undefined`(0) **单列一档**。
        // ------------------------------------------------------------
        //  A：**掉线那一档**（原版 `…_d__322__MoveNext.c:144` 判对面 · `FailedToReconnectAfterDisconnect.c:32` 判自己）
        var ctxDown = Battle(new[] { Unit("A", 1, 1, 1), Unit("F1", 1, 1, 1), Unit("F2", 1, 1, 1) },
                             new[] { Unit("X", 1, 1, 1), Unit("Y", 1, 1, 1), Unit("Z", 1, 1, 1) });
        RuleCore.Forfeit(ctxDown, 0, BattleResult.Disconnect);
        CheckTrue(ctxDown.Events.Exists(e => e.Contains("[BattleResult] Disconnect(3) seat=0")),
                  "★ 掉线那一档 ⇒ 日志里写明 **`Disconnect`(3)**"
                + "（原版判据 = `DeadHero(对面, 3)`：第三个实参就是 3）");
        CheckTrue(!ctxDown.Events.Exists(e => e.Contains("[BattleResult] Forfeit(2)")),
                  "★ **反向（与上一条成对的那一半）**：这一局**不许**出现「投降」那一档的 token"
                + " —— 没有这一条，「两个码都写进去」或「写死成 2」也照样绿（弱断言）");
        Check(ctxDown.ForfeitedBy, 0, "★ …码只管日志：谁弃权 / 谁获胜那一套一个字都没变");

        //  B：**投降那一档**（原版 `ClickExitBattle.c:59` 我点退出 · `ReceiveEnemyForfeit.c:37` 对面投降）
        var ctxFq = Battle(new[] { Unit("A", 1, 1, 1), Unit("F1", 1, 1, 1), Unit("F2", 1, 1, 1) },
                           new[] { Unit("X", 1, 1, 1), Unit("Y", 1, 1, 1), Unit("Z", 1, 1, 1) });
        RuleCore.Forfeit(ctxFq, 1, BattleResult.Forfeit);
        CheckTrue(ctxFq.Events.Exists(e => e.Contains("[BattleResult] Forfeit(2) seat=1")),
                  "★ 投降那一档 ⇒ 日志里写明 **`Forfeit`(2)**（原版那两跳的第三个实参都是 2）");
        CheckTrue(!ctxFq.Events.Exists(e => e.Contains("[BattleResult] Disconnect(3)")),
                  "★ **反向**：投降这一局**不许**出现掉线那一档的 token"
                + " —— 与 A 组合起来 = **两档真的分辨得出**（只断一条的话，两档可以同时绿）");

        //  C：**形参默认值** —— 不传码 = 本方法今天那个语义（「有人投降」）
        var ctxDef = Battle(new[] { Unit("A", 1, 1, 1), Unit("F1", 1, 1, 1), Unit("F2", 1, 1, 1) },
                            new[] { Unit("X", 1, 1, 1), Unit("Y", 1, 1, 1), Unit("Z", 1, 1, 1) });
        RuleCore.Forfeit(ctxDef, 0);
        CheckTrue(ctxDef.Events.Exists(e => e.Contains("[BattleResult] Forfeit(2) seat=0")),
                  "★ 不传码 ⇒ 默认 **`Forfeit`(2)**（`Forfeit` 这个名字今天就是这个语义、玩家那颗钮也是它）"
                + " —— 🧨 改坏法：改掉形参默认值 ⇒ 只红这一条");

        //  D：**判不出理由** ⇒ `Undefined`(0)，它是一个**独立可辨**的状态，⛔ 不许拿 2 顶替
        var ctxUnk = Battle(new[] { Unit("A", 1, 1, 1), Unit("F1", 1, 1, 1), Unit("F2", 1, 1, 1) },
                            new[] { Unit("X", 1, 1, 1), Unit("Y", 1, 1, 1), Unit("Z", 1, 1, 1) });
        RuleCore.Forfeit(ctxUnk, 0, BattleResult.Undefined);
        CheckTrue(ctxUnk.Events.Exists(e => e.Contains("[BattleResult] Undefined(0) seat=0")),
                  "★ 拿不到理由时**如实写 `Undefined`(0)**（今天唯一这么传的是录像重放那一跳 ——"
                + "录像里没记这个码，`BattleDriver.PlayReplay` 不许拿 `Forfeit` 顶替）");
        CheckTrue(!ctxUnk.Events.Exists(e => e.Contains("[BattleResult] Forfeit(2)")),
                  "★ **反向**：它**不冒充**投降那一档"
                + "（🧨 把 `Undefined` 折成 `Forfeit`、或给它一个「反正看起来像投降」的兜底 ⇒ 本条红）");
    }

    /// <summary>
    /// 🆕 2026-10-18（**A985⑩**）：**正常打完也带理由码** `BattleVictory`(1)。
    ///
    /// 判据 = 原版 `BattleManager__FinishResolvingAction.c:84` 那句
    /// `BattleManager__DeadHero(param_1, …, 1)`（第三个实参 = `BattleResult.BattleVictory`）——
    /// 原版**不是只有「投降 / 掉线」才带码**，「督军倒下、正常打完」那一跳也带。
    /// 🔴 它在本工程里的落点 = `RuleCore.CheckWinner` 里那一行 `[BattleResult] …` token
    ///    （和 `Forfeit` **同一个口、同一种形状**；码**不进 `ctx` 任何状态**、不进协议、不过网）。
    /// ⚠️ 一律认那个 **token**，⛔ 不认中文措辞 —— 「别拿给人看的句子当逻辑」。
    /// ⚠️ ⛔ **别用裸词 `BattleVictory` 当过滤词**：平局那一支的**说明行**里就写着这个词
    ///    （那是给人看的一句话，不是码）—— 本仓已有先例（「被测代码自己会打印的东西别当断言过滤词」）。
    ///
    /// 🧨 **灭自证（这几条合起来才闭合）**：
    ///   · ①② **两侧各一条** ⇒ **把 `seat` 写死成任何常数**都会红一条；
    ///   · ③ **投降那一路**只许有 `Forfeit`(2) ⇒ 「两档都写一条 / 无脑全记」红；
    ///   · ④ **平局那一路不许有码** ⇒ 「凡分出胜负就记一条」红；
    ///   · 另加一条 **计数**（这一局只许 1 行 `[BattleResult] …`）⇒ 「每回合记一次 / 记两遍」红。
    ///   ⇒ 没有任何一种「把被测实现和它的检测器一起改回去」的写法能同时满足这五条。
    /// </summary>
    static void TestBattleVictoryCode()
    {
        // ① 正例：**P1 的督军**被打死 ⇒ 码 `BattleVictory`(1)、座位 = **1**（倒下的那一位）
        var a = Battle(new[] { Unit("A", 1, 40, 40), Unit("F1", 1, 1, 1), Unit("F2", 1, 1, 1) },
                       new[] { Unit("X", 1, 1, 1), Unit("Y", 1, 1, 1), Unit("Z", 1, 1, 1) });
        ToP1Turn(a, 3);
        Place(a, 0, 3, Unit("A", 1, 40, 40));
        CheckCode(RuleCore.DeclareAttack(a, 0, 3, 1, BoardSpec.WarlordSlot), RuleCodes.OK,
                  "正常打完那一局：可以攻击敌方督军");
        Check(a.Winner, 1, "…P1 的督军倒下 ⇒ P0 胜");
        CheckTrue(a.Events.Exists(e => e.Contains("[BattleResult] BattleVictory(1) seat=1")),
                  "★ **正常打完（督军倒下）也带理由码** `BattleVictory`(1)，座位 = **倒下的那一位**"
                + "（原版判据 = `FinishResolvingAction.c:84` 的 `DeadHero(_, _, 1)`）"
                + " —— 🧨 改坏法：把这一句 `ctx.Log` 删掉、或把码改成别的档 ⇒ 本条红");
        CheckTrue(!a.Events.Exists(e => e.Contains("[BattleResult] Forfeit(2)")),
                  "★ **反向**：这一局**不是**投降那一档（两条码一起写 ⇒ 本条红）");
        Check(a.Events.FindAll(e => e.Contains("[BattleResult] ")).Count, 1,
              "★ 这一局**只记 1 条** `[BattleResult]`（原版那一跳每场只调一次 `DeadHero`）"
            + " —— 🧨 每回合记一次、或记两遍（token 与措辞各记一条）⇒ 本条红");

        // ② 反例的另一侧：**P0 的督军**被疲劳打死 ⇒ 座位必须是 **0**
        //    （①+② 合起来 = 灭自证：`seat` 写死成常数必红一条）
        var b = Battle(new[] { Unit("A", 1, 1, 1), Unit("F1", 1, 1, 1), Unit("F2", 1, 1, 1) },
                       new[] { Unit("X", 1, 1, 1), Unit("Y", 1, 1, 1), Unit("Z", 1, 1, 1) });
        b.Players[0].Deck.Clear();
        b.Players[0].Warlord.Health = 1;
        RuleCore.Draw(b, 0);                                  // 抽空 ⇒ 疲劳 1 点 ⇒ 督军倒下
        Check(b.Winner, 2, "…换成 P0 的督军倒下 ⇒ P1 胜");
        CheckTrue(b.Events.Exists(e => e.Contains("[BattleResult] BattleVictory(1) seat=0")),
                  "★ **倒的是 0 号位时就写 `seat=0`**（座位跟着「谁倒下」走，不是个常数）");
        CheckTrue(!b.Events.Exists(e => e.Contains("[BattleResult] BattleVictory(1) seat=1")),
                  "★ **反向**：⚠️ 这两条**缺一不可** —— 只断①的话，把 `seat` 写死成 1 也照样绿（弱断言）");

        // ③ 投降那一路：只有 `Forfeit`(2)，⛔ 不许出现 `BattleVictory` 那一档的 token
        var c = Battle(new[] { Unit("A", 1, 1, 1), Unit("F1", 1, 1, 1), Unit("F2", 1, 1, 1) },
                       new[] { Unit("X", 1, 1, 1), Unit("Y", 1, 1, 1), Unit("Z", 1, 1, 1) });
        RuleCore.Forfeit(c, 1);
        CheckTrue(c.Events.Exists(e => e.Contains("[BattleResult] Forfeit(2) seat=1")),
                  "★ **投降那一路**照旧是 `Forfeit`(2)（`A913` 那批钉住的口径，本笔一个字没动）");
        CheckTrue(!c.Events.Exists(e => e.Contains("[BattleResult] BattleVictory(1)")),
                  "★ **灭自证**：投降这一局**不许**出现 `BattleVictory` 那一档的 token"
                + "（🧨 无脑「凡判负就记一条」的写法在本条与①之间必红一条）");

        // ④ 平局那一路（双方督军同时倒下）：**不记**理由码 —— 原版没有对应的 `DeadHero` 调用点
        var d = Battle(new[] { Unit("A", 1, 1, 1), Unit("F1", 1, 1, 1), Unit("F2", 1, 1, 1) },
                       new[] { Unit("X", 1, 1, 1), Unit("Y", 1, 1, 1), Unit("Z", 1, 1, 1) });
        d.Players[0].Warlord.Health = 0;
        d.Players[1].Warlord.Health = 0;
        Check(RuleCore.CheckWinner(d), 3, "平局那一局：双方督军同时倒下 ⇒ `Winner 3`");
        Check(d.Events.FindAll(e => e.Contains("[BattleResult] ")).Count, 0,
              "★ **平局一条码都不记**（`[BattleResult] ` 前缀 = 「这一局给出了一条理由码」）"
            + " —— 原版那一跳只对应「**某一位**督军倒下」，双方同时倒没有对应调用点"
            + " —— 🧨 把码挪到「凡分胜负就记」的位置 ⇒ 本条红");
        CheckTrue(d.Events.Exists(e => e.Contains("不记理由码")),
                  "★ …而且**不静默**：日志里如实写清「这一局不记理由码、为什么不记」"
                + "（⚠️ 本条认的是措辞 —— 它验的是「出声」这件事本身；⛔ 别把它当逻辑用的判据）");
    }

    static void TestDrawIsDraw()
    {
        var ctx = Battle(new[] { Unit("A", 1, 1, 1), Unit("F1", 1, 1, 1), Unit("F2", 1, 1, 1) },
                         new[] { Unit("X", 1, 1, 1), Unit("Y", 1, 1, 1), Unit("Z", 1, 1, 1) });
        ctx.Players[0].Warlord.Health = 0;
        ctx.Players[1].Warlord.Health = 0;
        Check(RuleCore.CheckWinner(ctx), 3, "双方督军同时倒下 → 平局");
        Check(ctx.Winner, 3, "ctx.Winner 也记成 3");
    }

    static void TestFatigue()
    {
        var ctx = Battle(new[] { Unit("A", 1, 1, 1), Unit("F1", 1, 1, 1), Unit("F2", 1, 1, 1) },
                         new[] { Unit("X", 1, 1, 1), Unit("Y", 1, 1, 1), Unit("Z", 1, 1, 1) });
        ctx.Players[0].Deck.Clear();

        Check(ctx.Players[0].Warlord.Health, 30, "抽空之前督军 30 血");
        RuleCore.Draw(ctx, 0);
        Check(ctx.Players[0].Fatigue, 1, "第 1 次抽空 → 疲劳 1");
        Check(ctx.Players[0].Warlord.Health, 29, "督军挨 1 伤（30→29）");
        RuleCore.Draw(ctx, 0);
        Check(ctx.Players[0].Fatigue, 2, "第 2 次 → 疲劳 2");
        Check(ctx.Players[0].Warlord.Health, 27, "督军再挨 2 伤（29→27）");

        // 疲劳能打死督军 —— 每次抽牌后都必须复查胜负
        ctx.Players[0].Warlord.Health = 1;
        RuleCore.Draw(ctx, 0);
        CheckTrue(ctx.Players[0].Warlord.Health <= 0, "疲劳把督军打死了");
        Check(ctx.Winner, 2, "督军被疲劳打死 → 对方胜（Draw 内部复查了胜负）");
    }

    // ==================================================================
    //  确定性
    // ==================================================================

    static void TestDeterminism()
    {
        var pool = CardDatabase.Load();
        if (pool.Count == 0) { CheckTrue(false, "卡表没加载上，确定性测试跳过"); return; }

        var factions = CardDatabase.Factions(pool);
        string f = factions[0];

        var a = RuleCore.NewBattle(DeckBuilder.StarterDeck(pool, f, 30, new System.Random(7)),
                                   DeckBuilder.StarterDeck(pool, f, 30, new System.Random(9)),
                                   seed: 20260911);
        var b = RuleCore.NewBattle(DeckBuilder.StarterDeck(pool, f, 30, new System.Random(7)),
                                   DeckBuilder.StarterDeck(pool, f, 30, new System.Random(9)),
                                   seed: 20260911);

        Check(a.Players[0].Hand.Count, b.Players[0].Hand.Count, "同种子 → 手牌张数一致");
        Check(a.Players[0].Deck.Count, b.Players[0].Deck.Count, "同种子 → 牌库张数一致");

        bool sameHand = true, sameDeck = true;
        for (int i = 0; i < a.Players[0].Hand.Count; i++)
            if (a.Players[0].Hand[i].Card.Name != b.Players[0].Hand[i].Card.Name) { sameHand = false; break; }
        for (int i = 0; i < a.Players[0].Deck.Count; i++)
            if (a.Players[0].Deck[i].Card.Name != b.Players[0].Deck[i].Card.Name) { sameDeck = false; break; }

        CheckTrue(sameHand, "同种子 → 起手逐张一致（顺序也一致）");
        CheckTrue(sameDeck, "同种子 → 洗牌结果逐张一致");

        // 换个种子应该不一样（防「压根没洗牌」这种假通过）
        var c = RuleCore.NewBattle(DeckBuilder.StarterDeck(pool, f, 30, new System.Random(7)),
                                   DeckBuilder.StarterDeck(pool, f, 30, new System.Random(9)),
                                   seed: 99999);
        bool differs = false;
        for (int i = 0; i < a.Players[0].Deck.Count; i++)
            if (a.Players[0].Deck[i].Card.Name != c.Players[0].Deck[i].Card.Name) { differs = true; break; }
        CheckTrue(differs, "换种子 → 洗牌结果不同（证明真的在洗）");
    }

    // ==================================================================
    //  端到端：用真卡表跑完一局
    // ==================================================================

    static int FirstFreeSlot(PlayerState p)
    {
        for (int s = 0; s < BoardSpec.Size; s++)
            if (BoardSpec.IsDeployable(s) && p.Board[s] == null) return s;
        return -1;
    }

    /// <summary>
    /// 贪心出牌 + 全量攻击。够验证「规则能跑完一局分出胜负」，不是 AI 设计。
    /// 打不死就靠疲劳分出结果 —— 那也顺带验了疲劳。
    /// </summary>
    static void PlayGreedyTurn(BattleContext ctx)
    {
        int p = ctx.Active;
        var ps = ctx.Players[p];

        // 出牌：反复挑「能打得起的最贵的一张」放到第一个空格
        for (int guard = 0; guard < 40 && !ctx.IsOver; guard++)
        {
            int best = -1, bestCost = -1;
            for (int i = 0; i < ps.Hand.Count; i++)
            {
                var card = ps.Hand[i].Card;
                if (!card.IsUnit || card.Cost > ps.Energy) continue;
                if (card.Cost > bestCost) { bestCost = card.Cost; best = i; }
            }
            if (best < 0) break;
            int slot = FirstFreeSlot(ps);
            if (slot < 0) break;
            if (RuleCore.PlayCard(ctx, p, best, slot) != RuleCodes.OK) break;
        }

        // 攻击：每个己方单位打一次，目标按槽位顺序取第一个合法的
        for (int s = 0; s < BoardSpec.Size && !ctx.IsOver; s++)
        {
            var u = ps.Board[s];
            if (u == null || u.Exhausted) continue;
            if (u.IsWarlord && u.Attack <= 0) continue;
            for (int ts = 0; ts < BoardSpec.Size; ts++)
            {
                if (ctx.Players[1 - p].Board[ts] == null) continue;
                if (RuleCore.DeclareAttack(ctx, p, s, 1 - p, ts, ranged: false) == RuleCodes.OK) break;
            }
        }
    }

    static void TestFullGameWithRealCards()
    {
        var pool = CardDatabase.Load();
        if (pool.Count == 0) { CheckTrue(false, "卡表没加载上，端到端测试跳过"); return; }

        var factions = CardDatabase.Factions(pool);
        string f0 = factions[0];
        string f1 = factions.Count > 1 ? factions[1] : factions[0];

        var deck0 = DeckBuilder.StarterDeck(pool, f0, DeckBuilder.ClassicDeckSize, new System.Random(11));
        var deck1 = DeckBuilder.StarterDeck(pool, f1, DeckBuilder.ClassicDeckSize, new System.Random(22));

        // 🆕 2026-09-29：`StarterDeck` 现在会**补一张防御卡**（**独立的一格**、不算进那 30 张，
        //   见 `DeckBuilder.StarterDeck` 末尾那段）⇒ 数的是「30 + 防御卡张数」。
        //   ⚠️ 这里是**随便挑的两个阵营**（`factions[0]/[1]`），有的阵营可能一张防御卡都没有 ⇒ 不能写死 1。
        int def0 = 0;
        foreach (var c in deck0) if (c.Type == "defence") def0++;
        Check(deck0.Count, DeckBuilder.ClassicDeckSize + def0,
              $"P1 牌组凑满 {DeckBuilder.ClassicDeckSize} 张 + 防御卡 {def0} 张（独立的一格）");
        Check(deck0[0].Type, "hero", "牌组第 0 张是督军");

        var curve = DeckBuilder.CostCurve(deck0);
        Debug.Log(P + "   P1 法术力曲线：" + string.Join(" ", curve));

        var ctx = RuleCore.NewBattle(deck0, deck1, seed: 20260911);
        Check(ctx.Players[0].Hand.Count, RuleCore.StartHand, "起手 3 张");

        int turnLimit = 200;
        while (!ctx.IsOver && ctx.Turn < turnLimit)
        {
            RuleCore.BeginTurn(ctx);
            PlayGreedyTurn(ctx);
            if (ctx.IsOver) break;
            RuleCore.EndTurn(ctx);
        }

        CheckTrue(ctx.IsOver, $"打完一局出结果了（共 {ctx.Turn} 回合，上限 {turnLimit}）");
        CheckTrue(ctx.Winner >= 1 && ctx.Winner <= 3, $"赢家 = {ctx.Winner}（1/2 胜，3 平局）");

        string who = ctx.Winner == 3 ? "平局" : $"P{ctx.Winner} 胜";
        Debug.Log(P + $"   对局结果：{who}，{ctx.Turn} 回合；"
                    + $"P1 督军剩 {Math.Max(0, ctx.Players[0].Warlord.Health)}，"
                    + $"P2 督军剩 {Math.Max(0, ctx.Players[1].Warlord.Health)}");
        Debug.Log(P + $"   末 6 条事件：");
        int from = Math.Max(0, ctx.Events.Count - 6);
        for (int i = from; i < ctx.Events.Count; i++) Debug.Log(P + "     · " + ctx.Events[i]);

        // 一局跑完账面要自洽
        CheckTrue(ctx.Players[0].Board[BoardSpec.WarlordSlot] != null, "督军始终留在槽 4 上");
        CheckTrue(ctx.Players[1].Board[BoardSpec.WarlordSlot] != null, "对方督军也在槽 4 上");
    }

    // ==================================================================
    //  分层规矩：`Core/` 不碰 Unity（源文扫描 · A941）
    // ==================================================================

    /// <summary>
    /// **A941（2026-10-18）**：`Core/` 只许碰 `UnityEngine.Debug` / `UnityEngine.Random`。
    ///
    /// 🔴 **这条规矩原来破着，而且没有任何可观测点**：`Core/TutorialScript.cs` 拿
    ///    `#if UNITY_5_3_OR_NEWER` 把 `Resources.Load` + `JsonUtility.FromJson` 包了起来 ——
    ///    Unity 下编得过、探针下走 `#else`，**两条路都不报错**；而它捅破的正是
    ///    `工具/ruleprobe` 那条边界（探针只编 `Core/*.cs`、用一份极简桩在 net8 下跑真解析器）。
    ///    2026-10-18 把那一跳搬进了 `Data/TutorialDatabase.cs`；换乘点 = `TutorialData` 的
    ///    `static partial void LoadFromUnity();`（探针下只有声明 ⇒ C# 连调用一起抹掉 ⇒ = 老 `#else` 行为）。
    ///
    /// **判据 = 在本测试里现读源文、现扫**（⛔ 不信任何「我记得没写」），扫的是**引用**、不是**提及**：
    ///    ① 禁用词：`Core/*.cs` 的**代码**里一个都不许有（那两处 + 「`using UnityEngine`」这道总闸）；
    ///    ② 白名单：代码里的 `UnityEngine.X` 只许是 `Debug` / `Random`。
    /// ⚠️ **必须先剥注释与字面量**：`TutorialScript.cs` 的类头注里**故意**写着 `Resources` / `JsonUtility`
    ///    （那是解释「为什么搬走」的正文），Core 的报错文案里也**允许**提到这些名字
    ///    ⇒ 不剥就会把「提及」当「引用」报红（**假红比漏报更贵** —— 见 CLAUDE.md「红了先派只读诊断代理」）。
    ///    ⚠️ 剥掉字面量**不会漏报**：Core 里没有 `using UnityEngine;`（那条本身就在禁用词表里），
    ///       要碰 Unity 就只剩全限定写法一种，而那已经被 ①② 抓死（下面 ㈠/㈡ 那几条合成样本实测过）。
    /// 🔴 **四条「灭自证」反制**（少一条，这个测试都可能被写成永远绿）：
    ///    ㈠ 剥注释器先用**合成样本**验三件事（行注释 / 块注释 / `"a // b"` 里那个假注释）；
    ///    ㈡ 另造三份**假源文**喂同一个扫描器：代码里写禁用词**要报**、注释里提**不许报**、
    ///       字符串里提**不许报** —— 「有问题报不出来」和「没问题乱报」都要挡住；
    ///    ㈢ 剥完「代码」还在（`namespace RuleEngine` 每个文件一处）——否则「把整篇吞成空串」也是 0 命中；
    ///    ㈣ 源文件**个数**要对得上（路径写错 ⇒ 扫到 0 个文件 ⇒ 也是 0 命中）。
    /// </summary>
    static void TestCoreLayerPurity()
    {
        // ---- ㈠ 剥注释器自己（合成样本，不碰真文件）----
        Check(StripCsComments("int a = 1; // Resources.Load").Trim(), "int a = 1;",
              "剥注释器：`//` 之后被吃掉（行注释）");
        Check(StripCsComments("/* JsonUtility.FromJson */ int x;").Trim(), "int x;",
              "剥注释器：`/* */` 块注释被吃掉");
        Check(StripCsComments("var s = \"a // b\";").Trim(), "var s = \"\";",
              "剥注释器：字符串**内容**整体剥掉，且里面那个 `//` 不当注释（`\"a // b\"` → `\"\"`）");

        // ---- ㈡ 三份假源文喂同一个扫描器：该报的要报、不该报的不许报 ----
        //    ⛔ 不做这一步的话，「扫描器恒返回 0 命中」也能让下面两条判据全绿。
        Check(ScanCoreText("FakeCode.cs",
                "namespace X { static class Y { static void Z() { UnityEngine.Resources.Load(\"a\"); } } }\n")
                .Banned.Count, 1,
              "反制：**代码里**写 `UnityEngine.Resources.Load` ⇒ 抓得到（判据真能报）");
        var rCmt = ScanCoreText("FakeComment.cs",
                "// Resources. JsonUtility. TextAsset using UnityEngine\n"
                + "/* JsonUtility.FromJson */\n"
                + "namespace X { static class Y { static void Z() { UnityEngine.Debug.Log(\"ok\"); } } }\n");
        Check(rCmt.Banned.Count + rCmt.Unity.Count, 0,
              "反制：**注释里**提这些名字 ⇒ 不报（判据是「引用」、不是「提及」）");
        var rStr = ScanCoreText("FakeString.cs",
                "namespace X { static class Y { static void Z() "
                + "{ UnityEngine.Debug.Log(\"Resources. JsonUtility. TextAsset\"); } } }\n");
        Check(rStr.Banned.Count + rStr.Unity.Count, 0,
              "反制：**字符串里**提这些名字 ⇒ 不报（同上）");
        Check(ScanCoreText("FakeUsing.cs",
                "using UnityEngine;\nnamespace X { static class Y { static void Z() { GameObject o; } } }\n")
                .Banned.Count, 1,
              "反制：裸 `using UnityEngine;` ⇒ 抓得到（⚠️ `UnityEngine.` 那条白名单**抓不到它** —— 后面没有点）");

        string dir = System.IO.Path.Combine(Application.dataPath, "RuleEngine", "Core");
        if (!System.IO.Directory.Exists(dir))
        {
            CheckTrue(false, $"找得到 `{dir}`（源文扫描的前提；⛔ 不静默跳过）");
            return;
        }
        var files = System.IO.Directory.GetFiles(dir, "*.cs");
        Array.Sort(files);
        // ---- ㈣ 个数 ----
        CheckTrue(files.Length >= 20, $"扫到 {files.Length} 个 `Core/*.cs`（太少 = 路径不对，别当成全绿）");

        // ---- ①② 真文件 ----
        var r = ScanCoreSources(files);
        // ---- ㈢ 剥完「代码」还在（否则「把整篇吞成空串」也是 0 命中）----
        CheckTrue(CountOf(r.CodeAll, "namespace RuleEngine") >= files.Length,
                  $"剥注释器没把 `Core/*.cs` 吞掉：剥后 {r.CodeLen} / 原文 {r.RawLen} 字符，"
                  + "`namespace RuleEngine` 一个不少");
        Check(r.Banned.Count, 0, "`Core/` 的**代码**里 0 处 `using UnityEngine` / `Resources.` / "
              + "`JsonUtility.` / `TextAsset` / `Application.` / `PlayerPrefs.`" + HitDetail(r.Banned));
        Check(r.Unity.Count, 0, "`Core/` 的**代码**里 `UnityEngine.X` 只有 `Debug` / `Random`"
              + HitDetail(r.Unity));
    }

    // ==================================================================
    //  🆕 2026-10-18（A938）：教程执行器 · **引擎侧那一半**
    // ==================================================================
    //
    //  这一节**只验引擎**：卡上持久的攻击型（原版 `EntityScript.currentAttackType`，偏移 `+0x120`）、
    //  照它打的 `DeclareAttackByCurrentType`（原版 `AiScripted.ExecuteAction` 的 `Attack(30)` 那支），
    //  以及脚本「谁 / 打谁」的解析（`TutorialRules` 那三个方法，含**认不出就不猜**）。
    //  ⚠️ 「脚本真的被驱动 / 六档真的改了局面 / 录像能回放」在 `Editor/BattleScene.cs` 那一节
    //     （那边才有真 `BattleDriver` 与真关卡数据）。
    //
    //  判据（全部现读 `d:/2/tools/decomp_full/`）：
    //   · 初值 = **1**（`EntityScript__.ctor.c:5`），随后被 `CardScript__CardSetup.c:263-267` /
    //     `CardScript__ChooseAttackTypeAutomatically.c:10-12` 按 **`(近战 < 远程) + 1`** 覆盖
    //     ⇒ **远程更高才取远程、平手取近战**；
    //   · `ChangeToRanged/Melee` 走 `CardScript.ChangeAttackType(card, 2|1, true)`
    //     （`AiScripted__ExecuteAction.c:1201,:1249` → `CardScript__ChangeAttackType.c:15`）；
    //   · `Attack(30)` 读的正是这一格（`AiScripted__ExecuteAction.c:1139` 的 `uVar18`）。
    static void TestTutorialEngineHalf()
    {
        var emptyStage = new TutorialStageData { stage = 90, so = "<自检合成·引擎侧>" };

        // ------------------------------------------------------------
        //  ① 卡上攻击型的**初值**：原版 `(近战 < 远程) + 1`
        // ------------------------------------------------------------
        {
            var ctx = Battle(new[] { Unit("A", 1, 0, 9) }, new[] { Unit("X", 1, 0, 9) });
            var melee = Place(ctx, 0, 3, Ranged("MeleeHigh", 1, 4, 9, 0));
            var gun = Place(ctx, 0, 2, Ranged("RangedHigh", 1, 1, 9, 5));
            var tie = Place(ctx, 0, 1, Ranged("Tie", 1, 3, 9, 3));
            Check(melee.CurrentAttackType, UnitState.AttackTypeMelee,
                  "近战 4 / 远程 0 ⇒ 当前攻击型 = **1 近战**（原版 `CardSetup` 的 `(近战<远程)+1`）");
            Check(gun.CurrentAttackType, UnitState.AttackTypeRanged,
                  "近战 1 / 远程 5 ⇒ **2 远程**（远程更高才取远程）");
            Check(tie.CurrentAttackType, UnitState.AttackTypeMelee,
                  "★ **判别式**：近战 3 / 远程 3 **平手** ⇒ 取 **1 近战**（`(3<3)+1` = 1）"
                + "｜🧨 把算式写成 `<=` ⇒ 本条红");
        }

        // ------------------------------------------------------------
        //  ② 照卡上那一格打：`DeclareAttackByCurrentType`（原版 `Attack(30)`）
        //     🔴 **灭自证那一对**：同一句调用、同一套牌，**只改那一格** ⇒ 打出来的是两种伤害。
        // ------------------------------------------------------------
        {
            var ctxA = Battle(new[] { Unit("A", 1, 0, 9) }, new[] { Unit("X", 1, 0, 40) });
            var atkA = Place(ctxA, 0, 3, Ranged("Hybrid", 1, 1, 9, 5));      // 近战 1 / 远程 5
            var tgtA = Place(ctxA, 1, 3, Unit("T", 1, 0, 40));
            Check(atkA.CurrentAttackType, UnitState.AttackTypeRanged, "（前提）这一张当前是远程");
            Check(RuleCore.DeclareAttackByCurrentType(ctxA, 0, 3, 1, 3), RuleCodes.OK, "照当前攻击型打出去");
            Check(tgtA.Health, 35, $"挨的是**远程 5**（40 → {tgtA.Health}）");

            var ctxB = Battle(new[] { Unit("A", 1, 0, 9) }, new[] { Unit("X", 1, 0, 40) });
            var atkB = Place(ctxB, 0, 3, Ranged("Hybrid", 1, 1, 9, 5));
            var tgtB = Place(ctxB, 1, 3, Unit("T", 1, 0, 40));
            Check(RuleCore.SetCurrentAttackType(ctxB, 0, 3, UnitState.AttackTypeMelee), true,
                  "把这一格拨回近战（= 原版 `ChangeAttackType(card, 1, true)`）");
            Check(atkB.CurrentAttackType, UnitState.AttackTypeMelee, "★ 拨完就是近战（**持久状态**，不是一次性的）");
            Check(RuleCore.DeclareAttackByCurrentType(ctxB, 0, 3, 1, 3), RuleCodes.OK, "同一句调用再打一次");
            Check(tgtB.Health, 39, $"★ **判别式**：同一局面 ⇒ 这一下是**近战 1**（40 → {tgtB.Health}）"
                + " —— 与上面那一格**结构上不可能同时成立**（同一句调用、两种结果只差那一格）");
        }

        // ------------------------------------------------------------
        //  ③ 旧调用点**不许被改道**：`DeclareAttack` 省略 `ranged` 仍然 = 近战
        //     （这一条是「别把默认值改成读当前攻击型」的守门员 —— 全工程 60+ 处省略它）
        // ------------------------------------------------------------
        {
            var ctx = Battle(new[] { Unit("A", 1, 0, 9) }, new[] { Unit("X", 1, 0, 40) });
            var atk = Place(ctx, 0, 3, Ranged("Hybrid", 1, 1, 9, 5));        // 当前攻击型 = 远程
            var tgt = Place(ctx, 1, 3, Unit("T", 1, 0, 40));
            Check(atk.CurrentAttackType, UnitState.AttackTypeRanged, "（前提）卡上那一格是远程");
            Check(RuleCore.DeclareAttack(ctx, 0, 3, 1, 3), RuleCodes.OK, "旧调用点（省略 `ranged`）");
            Check(tgt.Health, 39, $"★ 它打的**仍然是近战 1**（40 → {tgt.Health}）—— `DeclareAttack` 的默认值"
                + "没被 `CurrentAttackType` 改道｜🧨 把默认值改成「读当前攻击型」⇒ 本条红（那会静默改掉 60+ 处）");
        }

        // ------------------------------------------------------------
        //  ④ 空格的读 / 写：如实返回 false（调用方出声），不静默
        // ------------------------------------------------------------
        {
            var ctx = Battle(new[] { Unit("A", 1, 0, 9) }, new[] { Unit("X", 1, 0, 9) });
            Check(RuleCore.SetCurrentAttackType(ctx, 0, 0, UnitState.AttackTypeRanged), false,
                  "空格上 `SetCurrentAttackType` ⇒ **false**（原版 `ChangeAttackType` 传 null 会抛，我们不抛但要如实报）");
            Check(RuleCore.CurrentAttackIsRanged(ctx, 0, 0), false, "空格读「是不是远程」⇒ **false**（不抛）");
            Check(RuleCore.SetCurrentAttackType(ctx, 5, 3, UnitState.AttackTypeRanged), false, "非法座位 ⇒ false");
        }

        // ------------------------------------------------------------
        //  ⑤ 脚本「谁」→ 我们的座位（原版 `AiScripted__GetActingCard.c` 那张表）
        // ------------------------------------------------------------
        {
            Check(TutorialRules.SideOfUnitType((int)ScriptedActionUnit.PlayerWarlord), 0, "10 PlayerWarlord ⇒ 座位 0");
            Check(TutorialRules.SideOfUnitType((int)ScriptedActionUnit.PlayerMinion), 0, "30 PlayerMinion ⇒ 座位 0");
            Check(TutorialRules.SideOfUnitType((int)ScriptedActionUnit.PlayerMinionLeft), 0, "31 ⇒ 座位 0（与 30 同路）");
            Check(TutorialRules.SideOfUnitType((int)ScriptedActionUnit.PlayerCardInHand), 0, "50 ⇒ 座位 0");
            Check(TutorialRules.SideOfUnitType((int)ScriptedActionUnit.AiWarlord), 1, "20 AiWarlord ⇒ 座位 1");
            Check(TutorialRules.SideOfUnitType((int)ScriptedActionUnit.EnemyMinion), 1, "40 ⇒ 座位 1");
            Check(TutorialRules.SideOfUnitType((int)ScriptedActionUnit.EnemyCardInHand), 1, "60 ⇒ 座位 1");
            Check(TutorialRules.SideOfUnitType(0), -1, "★ **判别式**：`None(0)` ⇒ **-1**（原版这一档 LogWarning + null）");
            Check(TutorialRules.SideOfUnitType(99), -1, "认不出的号 ⇒ -1（⛔ 不许默认成 0）");
        }

        // ------------------------------------------------------------
        //  ⑥ 脚本「谁」→ 场上的格号 / 手牌下标（**认不出就不猜**）
        // ------------------------------------------------------------
        {
            var ctx = Battle(new[] { Unit("Mine", 1, 1, 5) }, new[] { Unit("Foe", 1, 1, 5) });
            var me = Place(ctx, 0, 3, Unit("OnBoard", 1, 1, 5));
            Place(ctx, 1, 3, Unit("TheirGuy", 1, 1, 5));

            int side, slot; string why;
            Check(TutorialRules.FindBoardUnit(ctx, new TutorialUnitRef { unitType = 10 }, out side, out slot, out why),
                  true, "督军那一档**按类型就定得下来**（原版 `GetHero`，不需要 id）");
            Check(side == 0 && slot == BoardSpec.WarlordSlot, true, $"督军落在座位 0 的 {BoardSpec.WarlordSlot} 号格");

            Check(TutorialRules.FindBoardUnit(ctx, new TutorialUnitRef { unitType = 20 }, out side, out slot, out why),
                  true, "`AiWarlord(20)` 同理 ⇒ 座位 1 的督军格");
            Check(side == 1 && slot == BoardSpec.WarlordSlot, true, "AI 督军落在座位 1 的督军格");

            var byId = new TutorialUnitRef { unitType = 30, ourId = "OnBoard" };
            Check(TutorialRules.FindBoardUnit(ctx, byId, out side, out slot, out why), true,
                  "`PlayerMinion(30)` + `ourId` 命中 ⇒ 认得出是哪一格");
            Check(side == 0 && slot == 3 && me != null, true, "认出来的是 0 号位 3 号格那只");

            var noId = new TutorialUnitRef { unitType = 30, ourId = "", name = "" };
            Check(TutorialRules.FindBoardUnit(ctx, noId, out side, out slot, out why), false,
                  "★ **判别式**：`ourId` 空（产物解不出我们的卡 id）⇒ **false**，⛔ 不退回 `list[0]`"
                + "（原版 `GetChosenCard` 会那样做 —— 那会**静默打错目标**）");
            CheckTrue(!string.IsNullOrEmpty(why), "被拒时要给出**人话理由**（调用方拿它出声）：" + (why ?? "<null>"));

            var wrongId = new TutorialUnitRef { unitType = 30, ourId = "NotOnBoard" };
            Check(TutorialRules.FindBoardUnit(ctx, wrongId, out side, out slot, out why), false,
                  "★ 场上**没有**那一张 ⇒ 也 false（不是「随便挑一只」）");

            var theirGuy = new TutorialUnitRef { unitType = 40, ourId = "TheirGuy" };
            Check(TutorialRules.FindBoardUnit(ctx, theirGuy, out side, out slot, out why) && side == 1,
                  true, "`EnemyMinion(40)` 认的是**座位 1** 那一侧");

            // 手牌：`NewBattle` 已发过起手 ⇒ 我方手牌 = [Mine, …]（`shuffle:false` 时从牌库末尾抽，见 `Draw`）
            int hi = TutorialRules.FindHandIndex(ctx, new TutorialUnitRef { unitType = 50, ourId = "Mine" }, out why);
            Check(hi, 0, $"（前提）`50` + `ourId` ⇒ 我方手牌第 {hi} 张（`shuffle:false` 时起手第一张就是那张）");
            Check(TutorialRules.FindHandIndex(ctx, new TutorialUnitRef { unitType = 50, ourId = "Nobody" }, out why),
                  -1, "★ 手牌里没有那一张 ⇒ **-1**（理由非空，同上）");
            CheckTrue(!string.IsNullOrEmpty(why), "手牌认不出也给理由：" + (why ?? "<null>"));
        }

        // ------------------------------------------------------------
        //  ⑦ 六个脚本动作档：`ChangeToMelee` / `Attack` / `PlayCard` **真的改了引擎状态**
        //     （`ActiveAbility` 6 关 0 条 ⇒ 只留桩，见 `BattleScene` 那一节钉的出声）
        // ------------------------------------------------------------
        {
            // ⑦-a `ChangeToMelee`：把督军的攻击型拨成近战（原版 `ChangeAttackType(card, 1, true)`）
            var ctxC = Battle(new[] { Unit("A", 1, 0, 9) }, new[] { Unit("X", 1, 0, 9) });
            RuleCore.SetCurrentAttackType(ctxC, 0, BoardSpec.WarlordSlot, UnitState.AttackTypeRanged);
            var chAct = new TutorialAction
            {
                type = "ChangeToMelee",
                data = new[] { new TutorialActionData
                {
                    type = (int)ScriptedActionType.ChangeToMelee,
                    acting = new TutorialUnitRef { unitType = (int)ScriptedActionUnit.PlayerWarlord },
                } },
            };
            var scC = new TutorialScript(emptyStage);
            ScriptedActionDone gotC = default(ScriptedActionDone);
            bool firedC = false, okC = false;
            System.Action<BattleContext, TutorialAction, ScriptedActionDone, bool> cbC =
                (c, a, d, ok) => { gotC = d; okC = ok; firedC = true; };
            TutorialScript.Executed += cbC;
            try { Check(scC.ExecuteAction(ctxC, chAct), true, "`ChangeToMelee` 这一档**执行成功**"); }
            finally { TutorialScript.Executed -= cbC; }
            Check(ctxC.Players[0].Warlord.CurrentAttackType, UnitState.AttackTypeMelee,
                  "★ 引擎状态真的变了：督军的当前攻击型 = **近战**");
            Check(firedC && okC, true, "★ **第三条记账口发出来了**（`TutorialScript.Executed`，带 `ok = true`）"
                + " —— 录像靠它才记得到这条动作");
            Check(gotC.Kind, ScriptedActionType.ChangeToMelee, "记账口带的大类是 `ChangeToMelee`");
            Check(gotC.AttackType, UnitState.AttackTypeMelee, "记账口带的「改成哪一档」= 近战");
            Check(gotC.Seat, 0, "记账口带的座位 = 0");

            // ⑦-a′ 判别式：同一张脚本、同一个局面，**反过来**那一档 ⇒ 拨成远程
            var ctxC2 = Battle(new[] { Unit("A", 1, 0, 9) }, new[] { Unit("X", 1, 0, 9) });
            var chAct2 = new TutorialAction
            {
                type = "ChangeToRanged",
                data = new[] { new TutorialActionData
                {
                    type = (int)ScriptedActionType.ChangeToRanged,
                    acting = new TutorialUnitRef { unitType = (int)ScriptedActionUnit.PlayerWarlord },
                } },
            };
            new TutorialScript(emptyStage).ExecuteAction(ctxC2, chAct2);
            Check(ctxC2.Players[0].Warlord.CurrentAttackType, UnitState.AttackTypeRanged,
                  "★ **判别式**：换成 `ChangeToRanged` ⇒ 拨成**远程**（一近一远 ⇒ 不是「恒改同一个值」）");

            // ⑦-a″ 认不出就不猜：acting 的 `ourId` 空 + 是「部队」那一档 ⇒ 不执行、记账 + 出声
            var ctxC3 = Battle(new[] { Unit("A", 1, 0, 9) }, new[] { Unit("X", 1, 0, 9) });
            var scC3 = new TutorialScript(emptyStage);
            var chBad = new TutorialAction
            {
                type = "ChangeToMelee",
                data = new[] { new TutorialActionData
                {
                    type = (int)ScriptedActionType.ChangeToMelee,
                    acting = new TutorialUnitRef { unitType = (int)ScriptedActionUnit.PlayerMinion, ourId = "" },
                } },
            };
            Check(scC3.ExecuteAction(ctxC3, chBad), false, "★ 认不出「要改的是哪一张」⇒ **不执行**（返回 false）");
            int badN; scC3.Unresolved.TryGetValue(ScriptedActionType.ChangeToMelee, out badN);
            Check(badN, 1, "★ 而且**记了账**（`Unresolved`）—— 不许静默跳过");

            // ⑦-b `Attack(30)`：脚本驱动的一刀**真的打在 AI 督军身上**
            var ctxD = Battle(new[] { Unit("A", 1, 0, 9) }, new[] { Unit("X", 1, 0, 9) });
            Place(ctxD, 0, 3, Unit("Bruiser", 1, 3, 9));      // 近战 3 / 远程 0 ⇒ 当前攻击型 = 近战
            int hpBefore = ctxD.Players[1].Warlord.Health;
            var atkAct = new TutorialAction
            {
                type = "Attack",
                data = new[] { new TutorialActionData
                {
                    type = (int)ScriptedActionType.Attack,
                    acting = new TutorialUnitRef { unitType = (int)ScriptedActionUnit.PlayerMinion, ourId = "Bruiser" },
                    target = new TutorialUnitRef { unitType = (int)ScriptedActionUnit.AiWarlord },
                } },
            };
            Check(new TutorialScript(emptyStage).ExecuteAction(ctxD, atkAct), true, "`Attack` 这一档执行成功");
            Check(ctxD.Players[1].Warlord.Health, hpBefore - 3,
                  $"★ 打的是**近战 3**（AI 督军 {hpBefore} → {ctxD.Players[1].Warlord.Health}）"
                + " —— `Attack(30)` 读的就是卡上那一格（原版 `ExecuteAction.c:1139`）");

            // ⑦-b′ 目标认不出 ⇒ 不执行（**不猜一只顶着**）
            var ctxD2 = Battle(new[] { Unit("A", 1, 0, 9) }, new[] { Unit("X", 1, 0, 9) });
            Place(ctxD2, 0, 3, Unit("Bruiser", 1, 3, 9));
            var atkBad = new TutorialAction
            {
                type = "Attack",
                data = new[] { new TutorialActionData
                {
                    type = (int)ScriptedActionType.Attack,
                    acting = new TutorialUnitRef { unitType = (int)ScriptedActionUnit.PlayerMinion, ourId = "Bruiser" },
                    target = new TutorialUnitRef { unitType = (int)ScriptedActionUnit.PlayerMinion, ourId = "" },
                } },
            };
            int hpB = ctxD2.Players[1].Warlord.Health;
            Check(new TutorialScript(emptyStage).ExecuteAction(ctxD2, atkBad), false,
                  "★ 目标 `ourId` 空 ⇒ **不执行**（⛔ 不退回 `list[0]`）");
            Check(ctxD2.Players[1].Warlord.Health, hpB, "而且要**真的没打**（督军血量一点没动）");
        }

        // ------------------------------------------------------------
        //  ⑧ `PlayCard(20)`：脚本让 AI 从**它自己的手牌**里出一张（数据里 acting 全是 `EnemyCardInHand(60)`）
        // ------------------------------------------------------------
        {
            // 先手给 AI（`firstSeat: 1`）：`CanPlayCard` 要求 `p == ctx.Active`
            var ctxP = RuleCore.NewBattle(Deck(new[] { Unit("Filler", 1, 0, 1) }),
                                          Deck(new[] { Unit("FoeCard", 1, 1, 5) }),
                                          seed: 0, shuffle: false, firstSeat: 1);
            RuleCore.BeginTurn(ctxP);       // 发能量（起始 2）⇒ 1 费的牌真能打出去
            Check(ctxP.Active, 1, "（前提）这一局先手是 AI ⇒ `ctx.Active == 1`");
            int handBefore = ctxP.Players[1].Hand.Count;
            int hIdx = TutorialRules.FindHandIndex(ctxP,
                          new TutorialUnitRef { unitType = (int)ScriptedActionUnit.EnemyCardInHand, ourId = "FoeCard" },
                          out _);
            CheckTrue(hIdx >= 0, $"（前提）AI 手上有 `FoeCard`（下标 {hIdx}）");

            var playAct = new TutorialAction
            {
                type = "PlayCard",
                data = new[] { new TutorialActionData
                {
                    type = (int)ScriptedActionType.PlayCard,
                    acting = new TutorialUnitRef { unitType = (int)ScriptedActionUnit.EnemyCardInHand, ourId = "FoeCard" },
                } },
            };
            Check(new TutorialScript(emptyStage).ExecuteAction(ctxP, playAct), true, "`PlayCard` 这一档执行成功");
            Check(ctxP.Players[1].Hand.Count, handBefore - 1,
                  $"★ 那张牌**真的离手了**（{handBefore} → {ctxP.Players[1].Hand.Count}）");
            int onBoard = 0;
            for (int s = 0; s < BoardSpec.Size; s++)
            {
                var u = ctxP.Players[1].Board[s];
                if (u != null && !u.IsWarlord) onBoard++;
            }
            Check(onBoard, 1, $"★ 而且**真的落场了**（AI 场上多了一只，实得 {onBoard}）");
        }
    }

    /// <summary>命中清单（空 ⇒ 空串；只列头 10 条，别把日志刷爆）。</summary>
    static string HitDetail(List<string> hits)
    {
        if (hits.Count == 0) return "";
        var sb = new StringBuilder(" —— 命中：");
        for (int i = 0; i < hits.Count && i < 10; i++)
            sb.Append("\n").Append(P).Append("       · ").Append(hits[i]);
        if (hits.Count > 10) sb.Append("\n").Append(P).Append("       …（共 ").Append(hits.Count).Append(" 处）");
        return sb.ToString();
    }

    /// <summary>`code[at]` 在第几行（1 起）—— 只为报错文案给个坐标。</summary>
    static int LineOf(string code, int at)
    {
        int n = 1;
        for (int i = 0; i < at && i < code.Length; i++) if (code[i] == '\n') n++;
        return n;
    }

    /// <summary>`TestCoreLayerPurity` 一次扫描的结果。</summary>
    class CoreScan
    {
        /// <summary>禁用词命中（`文件 → 词`）。</summary>
        public readonly List<string> Banned = new List<string>();
        /// <summary>`UnityEngine.X` 白名单外的命中（`文件 → 类型`）。</summary>
        public readonly List<string> Unity = new List<string>();
        /// <summary>原文 / 剥注释后的字符数（㈢「黑洞」反制用）。</summary>
        public long RawLen, CodeLen;
        /// <summary>全部剥注释后的代码（㈢「黑洞」反制用）。</summary>
        public string CodeAll = "";
    }

    /// <summary>
    /// `Core/` 里**一个都不许出现**的 Unity 记号。
    /// 🔴 头一条是**总闸**：`using UnityEngine;` 里 `UnityEngine` **后面没有点**
    ///    ⇒ 下面那条 `UnityEngine.X` 白名单**抓不到它**（2026-10-18 用假源文实测过），
    ///    而它一出现，Unity 的名字就都能省掉限定前缀 ⇒ 必须单独盯。
    /// 其余五条 = 与资源装载 / 卡表 / 存档最容易被顺手拿来用的那几个。
    /// </summary>
    static readonly string[] CoreBannedTokens =
    {
        "using UnityEngine",
        "Resources.", "JsonUtility.", "TextAsset", "Application.", "PlayerPrefs.",
    };

    /// <summary>`Core/` 的代码里**只许**出现这两个 `UnityEngine.*`。</summary>
    static readonly HashSet<string> CoreAllowedUnity = new HashSet<string> { "Debug", "Random" };

    /// <summary>扫一批真源文件。</summary>
    static CoreScan ScanCoreSources(string[] files)
    {
        var texts = new List<KeyValuePair<string, string>>();
        foreach (var f in files)
            texts.Add(new KeyValuePair<string, string>(System.IO.Path.GetFileName(f),
                                                       System.IO.File.ReadAllText(f)));
        return ScanCoreTexts(texts);
    }

    /// <summary>扫一段假源文（㈡ 那几条反制用）。</summary>
    static CoreScan ScanCoreText(string name, string text)
    {
        return ScanCoreTexts(new List<KeyValuePair<string, string>>
        {
            new KeyValuePair<string, string>(name, text),
        });
    }

    /// <summary>剥注释 / 字面量之后找禁用词 + 查 `UnityEngine.X` 白名单。</summary>
    static CoreScan ScanCoreTexts(List<KeyValuePair<string, string>> texts)
    {
        var r = new CoreScan();
        var all = new StringBuilder();
        foreach (var kv in texts)
        {
            string code = StripCsComments(kv.Value);
            r.RawLen += kv.Value.Length; r.CodeLen += code.Length;
            all.Append(code);
            string name = kv.Key;
            foreach (var b in CoreBannedTokens)
            {
                int at = code.IndexOf(b, StringComparison.Ordinal);
                if (at >= 0) r.Banned.Add($"{name} → `{b}`（第 {LineOf(code, at)} 行附近）");
            }
            int idx = 0;
            while ((idx = code.IndexOf("UnityEngine.", idx, StringComparison.Ordinal)) >= 0)
            {
                int s = idx + "UnityEngine.".Length, e = s;
                while (e < code.Length && (char.IsLetterOrDigit(code[e]) || code[e] == '_')) e++;
                string ty = code.Substring(s, e - s);
                if (!CoreAllowedUnity.Contains(ty))
                    r.Unity.Add($"{name} → `UnityEngine.{ty}`（第 {LineOf(code, idx)} 行附近）");
                idx = e;
            }
        }
        r.CodeAll = all.ToString();
        return r;
    }

    /// <summary>`sub` 在 `s` 里出现几次（不重叠）。</summary>
    static int CountOf(string s, string sub)
    {
        int n = 0, i = 0;
        while ((i = s.IndexOf(sub, i, StringComparison.Ordinal)) >= 0) { n++; i += sub.Length; }
        return n;
    }

    /// <summary>
    /// 把 C# 源码里的**注释**、以及**字符串/字符字面量的内容**剥掉。
    /// ⚠️ **只为本节那两条判据服务，不是通用词法器** —— 要的就是「引用 / 提及」这个区分：
    ///    · `//` 与 `/* */`；`"…"` 与 `'…'` 的**内容** → 剥（那是讲解与文案，不是代码）；
    ///    · `"http://x"` 里那个 `//` **不当注释**（所以字面量分支必须排在注释分支前面）；
    ///    · 块注释里的换行保留 → 报错文案里的行号还算得准。
    /// 🔴 **实测（2026-10-18，镜像脚本 + 四条假源文）**：真 `Core/**` 剥完仍剩 **50%**
    ///    （22 个文件 1,483,880 → 742,695 字符）—— 这个工程的注释就是这么厚，
    ///    所以⚠️ **别拿「剥完还剩多少」当健康判据**（50% 那条线一碰就假红），用 `namespace` 计数那条。
    /// </summary>
    static string StripCsComments(string src)
    {
        var sb = new StringBuilder(src.Length);
        bool inStr = false, inChr = false, inLine = false, inBlock = false;
        int i = 0, n = src.Length;
        while (i < n)
        {
            char c = src[i], d = (i + 1 < n) ? src[i + 1] : '\0';
            if (inLine) { if (c == '\n') { inLine = false; sb.Append(c); } i++; continue; }
            if (inBlock)
            {
                if (c == '*' && d == '/') { inBlock = false; i += 2; continue; }
                if (c == '\n') sb.Append(c);
                i++; continue;
            }
            if (inStr || inChr)
            {
                if (c == '\\' && (i + 1) < n) { i += 2; continue; }        // 转义序列整体吞掉
                if (inStr && c == '"') { inStr = false; sb.Append(c); i++; continue; }
                if (inChr && c == '\'') { inChr = false; sb.Append(c); i++; continue; }
                i++; continue;                                             // ← 字面量的【内容】丢掉
            }
            if (c == '/' && d == '/') { inLine = true; i += 2; continue; }
            if (c == '/' && d == '*') { inBlock = true; i += 2; continue; }
            if (c == '"') { inStr = true; sb.Append(c); i++; continue; }
            if (c == '\'') { inChr = true; sb.Append(c); i++; continue; }
            sb.Append(c); i++;
        }
        return sb.ToString();
    }

